NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Leviticus'

CHAPTERS = {
    1: {
        1: 'Und der Herr rief Moses und redete mit ihm vom Festgezelt aus:',
        2: '"Sprich zu den Söhnen Israels und sage ihnen: \'Will jemand von euch ein Opfer dem Herrn darbringen, so könnt ihr eure Tieropfer nur vom Rind und Schaf darbringen.',
        3: 'Ist sein Opfer ein Rinderbrandopfer, dann soll er ein männliches, fehlerloses Tier zum Opfer bringen! Er soll es an des Festgezeltes Pforte bringen, daß ihm Wohlgefallen vor dem Herrn werde!',
        4: 'Er lege auf den Kopf des Brandopfers seine Hand. So wird es ihm angerechnet und wird ihm Sühne schaffen.',
        5: 'Dann schlachte er vor dem Herrn das junge Rind! Und die Priester, Aarons Söhne, sollen das Blut hintragen und mit dem Blute ringsum den Altar besprengen, der vor der Pforte des Festgezeltes ist!',
        6: 'Dann häute er das Brandopfer und zerstückle es!',
        7: 'Die Priester, Aarons Söhne, sollen Feuer auf dem Altar machen und auf das Feuer Holzscheite schichten!',
        8: 'Dann sollen Aarons Söhne, die Priester, auf den Holzscheiten des Altarfeuers die Stücke und den Kopf samt dem Fett auflegen!',
        9: 'Seine Eingeweide aber und Beine soll er mit Wasser waschen; dann lasse der Priester alles auf dem Altar aufdampfen als Brandopfer, als Mahl süßen Duftes für den Herrn!',
        10: 'Stammt sein Opfer für das Brandopfer vom Kleinvieh, von Lämmern oder Ziegen, dann soll er ein männliches, fehlerloses Tier zum Opfer bringen!',
        11: 'Er schlachte es auf der Nordseite des Altares vor dem Herrn! Die Priester aber, Aarons Söhne, sollen mit seinem Blut ringsum den Altar besprengen!',
        12: 'Dann zerlege er es in seine Teile! Mit seinem Kopf und Fett lege sie der Priester auf die Scheite des Altarfeuers!',
        13: 'Die Eingeweide und die Beine soll er im Wasser waschen! Dann bringe der Priester alles dar und lasse es auf dem Altar aufdampfen! Ein Brandopfer ist es, ein Mahl süßen Duftes für den Herrn.',
        14: 'Ist ein Vogelbrandopfer seine Opfergabe für den Herrn, dann bringe er von Turtel- oder jungen Tauben sein Opfer dar!',
        15: 'Der Priester bringe es zum Altar und drücke ihm den Kopf ab und lasse es auf dem Altar aufdampfen! An des Altares Wand werde sein Blut ausgepreßt!',
        16: 'Er trenne dem Vogel den Kropf samt seinem Unrat ab und werfe ihn neben den Altar ostwärts auf den Aschenhaufen!',
        17: 'Dann zerknicke er ihn an seinen Flügeln, ohne ihn zu teilen! Dann lasse ihn der Priester auf dem Altar aufdampfen auf Holzscheiten über dem Feuer! Ein Brandopfer ist es, ein Mahl süßen Duftes für den Herrn.\'"',
    },
    2: {
        1: '"\'Bringt jemand ein Speiseopfer dem Herrn dar, dann sei aus Feinmehl sein Opfer! Er gieße Öl darauf und gebe Weihrauch daran!',
        2: 'Dann bringe er es den Priestern, Aarons Söhnen! Und deren einer hebe eine Handvoll davon ab, von seinem Feinmehl, seinem Öl mit all seinem Weihrauch! Dann lasse der Priester auf dem Altar sein Brandteil aufdampfen, ein Mahl süßen Duftes für den Herrn.',
        3: 'Was vom Speiseopfer übrigbleibt, gehöre Aaron sowie seinen Söhnen als Hochheiliges von den Mählern des Herrn!',
        4: 'Willst du als Speiseopfer Backwerk bringen, dann seien es Feinmehlkuchen, ungesäuert und mit Öl bereitet, und Fladen, ungesäuert und mit Öl bestrichen!',
        5: 'Ist dein Opfer ein Speiseopfer in der Pfanne, dann sei es aus ungesäuertem, mit Öl bereitetem Feinmehl!',
        6: 'Zerbrich es in Einzelbissen. Gieße Öl darüber! Ein Speiseopfer ist es.',
        7: 'Ist dein Opfer ein Topfspeiseopfer, so werde es mit Öl aus feinem Mehl bereitet!',
        8: 'Dies Speiseopfer, daraus bereitet, bring dem Herrn dar! Man gebe es dem Priester, und er bringe es zum Altar!',
        9: 'Vom Speiseopfer nehme der Priester seinen Brandteil und lasse ihn auf dem Altar aufdampfen als ein Mahl süßen Duftes für den Herrn!',
        10: 'Was vom Speiseopfer übrigbleibt, gehöre Aaron und seinen Söhnen als Hochheiliges von den Mählern für den Herrn!',
        11: 'Wollt ihr dem Herrn ein Speiseopfer bringen, so darf es nicht aus Gesäuertem gemacht werden. Ihr dürft ja keinen Sauerteig und keinen Honig als Mahl für den Herrn aufdampfen lassen.',
        12: 'Als des ersten Abhubs Gabe sollt ihr sie dem Herrn darbringen! Aber auf den Altar dürfen sie nicht kommen zu süßem Duft.',
        13: 'Alle deine Speiseopfer sollst du salzen! Nicht sollst du deines Gottesbundes Salz bei deinem Speiseopfer fehlen lassen! Zu all deinen Opfern sollst du Salz bringen!',
        14: 'Bringst du dem Herrn ein Speiseopfer von den Erstlingsfrüchten, dann sollst du Ähren bringen, am Feuer geröstet, frische Graupen als Frühfruchtspeiseopfer!',
        15: 'Tu Öl daran und lege Weihrauch darauf! Ein Speiseopfer ist es.',
        16: 'Der Priester lasse von den Graupen und dem Öl mit seinem ganzen Weihrauch den Brandteil aufdampfen! Ein Mahl ist es für den Herrn.\'"',
    },
    3: {
        1: '"\'Ist seine Opfergabe ein Dankopfer und will er von Rindern sie darbringen, so sei es ein fehlerloses männlich oder weiblich Tier, das man dem Herrn darbringt!',
        2: 'Er lege auf den Kopf seiner Opfergabe die Hand und schlachte sie vor der Pforte des Festgezeltes! Die Priester, Aarons Söhne, sollen mit dem Blut den Altar ringsum besprengen!',
        3: 'Dann bringe er von dem Dankopfer dem Herrn ein Mahl, das Fett der Eingeweidedecke sowie alles Eingeweidefett,',
        4: 'die beiden Nieren und das Fett daran und das an den Lenden und an den Leberlappen! Bei den Nieren soll er es abtrennen!',
        5: 'Die Aaronssöhne sollen es auf dem Brandopferaltar aufdampfen lassen, auf den Holzscheiten im Feuer, als ein Mahl süßen Duftes für den Herrn!',
        6: 'Kommt aber ein Opfer als Dankopfer für den Herrn vom Kleinvieh her, dann sei es ein fehlerloses männlich oder weiblich Tier, das man darbringt!',
        7: 'Will man ein Lamm als Opfer bringen, so bringe man es vor den Herrn',
        8: 'und lege auf den Kopf seines Opfers die Hand und schlachte es vor dem Festgezelt! Die Aaronssöhne sollen mit dem Blut den Altar ringsum besprengen!',
        9: 'Dann bringe man von dem Dankopfer dem Herrn ein Mahl: das Beste, den ganzen Fettschwanz, - dicht am Schwanzbein trenne man ihn ab! - sowie das Fett der Eingeweidedecke und alles andere Eingeweidefett,',
        10: 'die beiden Nieren und das Fett daran und das an den Lenden und den Leberlappen! Bei den Nieren trenne man es ab!',
        11: 'Der Priester lasse es auf dem Altar aufdampfen als Mahl für den Herrn!',
        12: 'Ist aber eine Ziege seine Opfergabe, so bringe er sie vor den Herrn',
        13: 'und lege die Hand auf ihren Kopf und schlachte sie vor dem Festgezelt! Die Aaronssöhne sollen mit dem Blute den Altar ringsum besprengen!',
        14: 'Dann bringe er von seinem Opfer als Mahl für den Herrn das Fett der Eingeweidedecke und alles andere Fingeweidefett,',
        15: 'die beiden Nieren und das Fett daran und das an den Lenden und an den Leberlappen! Bei den Nieren soll man es abtrennen!',
        16: 'Der Priester lasse es auf dem Altar aufdampfen als Mahl zum süßen Duft! Dem Herrn gehört jedwedes Fett.',
        17: 'Für eure Geschlechter in all euren Siedlungen gilt allzeit dies Gebot: Fett und Blut dürft ihr nicht genießen.\'"',
    },
    4: {
        1: 'Und der Herr sprach zu Moses:',
        2: '"Sage dies zu den Söhnen Israels, wenn sich jemand unvorsätzlich gegen irgendein Gebot des Herrn verginge in Dingen, die man nicht tun darf, und handelte doch gegen eines von ihnen:',
        3: 'Sündigt der gesalbte Priester, wodurch Schuld auch auf das Volk kommt, dann bringe er für seine Sünde, die er getan, einen fehlerlosen jungen Stier dem Herrn zur Entsündigung dar!',
        4: 'Den Stier bringe er an die Pforte des Festgezeltes vor den Herrn und lege auf den Stierkopf die Hand und schlachte den Stier vor dem Herrn!',
        5: 'Dann nehme der gesalbte Priester vom Farrenblut und bringe es ins Festgezelt!',
        6: 'Der Priester tauche seinen Finger in das Blut und sprenge von dem Blut vor den Herrn siebenmal gegen des Heiligtumes Vorhang hin!',
        7: 'Und der Priester streiche von dem Blut an die Hörner des Altares für würziges Rauchwerk vor dem Herrn im Festgezelt! Alles andere Farrenblut soll er an den Sockel des Brandopferaltares vor der Tür des Festgezeltes gießen!',
        8: 'Er soll alles Fett vom Sündopferfarren abheben, das Fett der Eingeweidedecke und das Fett der Eingeweide,',
        9: 'die beiden Nieren und das Fett daran und das an den Lenden und den Leberlappen! Bei den Nieren soll er es abtrennen!',
        10: 'Wie es abgehoben wird vom Dankopferrinde, so lasse es der Priester auf dem Brandopferaltar aufdampfen!',
        11: 'Die Haut des Farren, all sein Fleisch samt Kopf und Beinen, Eingeweiden und Mist,',
        12: 'den ganzen Farren schaffe man vor das Lager an einen reinen Ort auf den Aschenhaufen! Dann verbrenne man ihn auf Holzscheiten im Feuer! Auf dem Aschenhaufen werde er verbrannt!',
        13: 'Irrt aber die ganze Versammlung Israels und ist es der Gemeinschaft nicht bewußt, daß sie etwas getan, was man nach des Herrn Geboten nicht tun darf, und werden sie so schuldig,',
        14: 'und wird die Sünde erkannt, durch die sie gesündigt, dann bringe die Gemeinschaft einen jungen Stier als Sündopfer dar! Sie bringe ihn vor das Festgezelt!',
        15: 'Die Ältesten der Gemeinschaft sollen auf den Farrenkopf die Hände vor dem Herrn legen! Dann schlachte man den Farren vor dem Herrn!',
        16: 'Dann bringe der gesalbte Priester vom Farrenblut ins Festgezelt!',
        17: 'Der Priester benetze seinen Finger mit dem Blut und sprenge es an den Vorhang vor dem Herrn siebenmal!',
        18: 'Er soll von dem Blute etwas an die Hörner des Altares vor dem Herrn im Festgezelt tun, und alles andere Blut soll er an des Brandopferaltares Sockel vor dem Festgezelt gießen!',
        19: 'Auch soll er all sein Fett abheben; dann lasse er es auf dem Altare aufdampfen!',
        20: 'Er tue mit dem Farren, wie er mit dem Sündenopferstier getan hat! So soll er auch mit ihm tun! So entsühne sie der Priester und suche ihnen Vergebung zu erwirken!',
        21: 'Den Farren schaffe man vors Lager und verbrenne ihn, wie man den vorigen Farren verbrannt hat! Das ist der Gemeinschaft Sündopfer.',
        22: 'Sündigt ein Fürst und tut unvorsätzlich etwas, was man nach des Herrn, seines Gottes, Geboten nicht tun darf, und wird er schuldig,',
        23: 'und wird ihm seine Sünde, durch die er gesündigt, bewußt, dann bringe er einen fehlerlosen Ziegenbock als ein Opfer dar!',
        24: 'Er lege auf des Bockes Kopf die Hand und schlachte ihn am Ort, wo man vor dem Herrn das Brandopfer sonst schlachtet! Ein Sündopfer ist es.',
        25: 'Der Priester nehme vom Sündopferblut etwas mit dem Finger und tue es an des Brandopferaltares Hörner, und an des Brandopferaltares Sockel soll er sein übriges Blut gießen.',
        26: 'All sein Fett soll er auf dem Altar aufdampfen lassen wie das Fett des Dankopfers! So entsühne ihn der Priester von seiner Sünde und suche ihm Verzeihung zu erwirken!',
        27: 'Sündigt unvorsätzlich eine einzelne Seele vom Volk des Landes, indem sie etwas tut, was man nach den Geboten des Herrn nicht tun darf, und wird sie schuldig',
        28: 'und wird ihr ihre Sünde, die sie getan, bewußt, dann bringe sie eine fehlerlose Ziege dar als Opfer für ihre Sünde, die sie getan!',
        29: 'Sie lege auf den Kopf des Sündopfers ihre Hand und schlachte an dem Ort des Brandopfers das Sündopfer!',
        30: 'Der Priester nehme von seinem Blute etwas mit dem Finger und tue es an des Brandopferaltares Hörner, und an den Sockel des Altares soll er sein Blut ausgießen!',
        31: 'All sein Fett soll er wegnehmen, wie man es vom Dankopfer wegnimmt! Der Priester lasse es auf dem Altar aufdampfen zum süßen Duft für den Herrn! So entsühne ihn der Priester und suche ihm Verzeihung zu erlangen!',
        32: 'Bringt er ein Lamm als Opfergabe für seine Sünde dar, so bringe er ein weibliches, fehlerloses Tier!',
        33: 'Er lege auf des Sündopfers Kopf die Hand und schlachte das Sündopfer an dem Ort, wo man das Brandopfer zu schlachten pflegt!',
        34: 'Der Priester nehme von des Sündopfers Blut etwas mit dem Finger und tue es an des Brandopferaltares Hörner, und an den Sockel des Altares soll er sein übriges Blut gießen!',
        35: 'All sein Fett soll er wegnehmen, wie das Fett des Lammes beim Dankopfer weggenommen wird! Der Priester lasse es aufdampfen auf dem Altar, der sonst für des Herren Mahl bestimmt ist! So entsühne ihn der Priester wegen der vollbrachten Sünde und suche ihm Verzeihung zu erwirken!"',
    },
    5: {
        1: '"Sündigt jemand, der ein Fluchwort hört, und könnte er Zeuge sein als Augenzeuge oder als einer, der Beweise liefern kann, macht aber keine Anzeige, so lädt er Schuld auf sich.',
        2: 'Oder jemand berührt Unreines oder das Aas eines unreinen Wildes oder eines unreinen Haustieres oder das Aas eines unreinen Gewürms, ist sich aber dessen nicht bewußt, so ist er dennoch unrein und schuldig.',
        3: 'Oder rührt jemand an die Unreinheit eines Menschen, irgendwelche Unreinheit, wodurch man unrein wird, ist sich aber dessen nicht bewußt, so wird er schuldig, wenn er dessen bewußt wird.',
        4: 'Oder jemand schwört recht unbesonnen, er wolle Schlechtes oder Gutes tun, was eben ein Mensch beim Schwören unbesonnen sprechen kann, ist sich aber dessen nicht bewußt, dann wird er an einem davon schuldig, wenn er sich dessen bewußt wird.',
        5: 'Fühlt sich jemand dieser Dinge schuldig, so erkenne er, daß er darin gefehlt,',
        6: 'und bringe dem Herrn als Buße für die vollbrachte Sünde zum Sündopfer ein Weibchen vom Kleinvieh, ein Schäfchen oder eine Ziege! So entsühne ihn der Priester von seiner Sünde!',
        7: 'Reicht sein Vermögen nicht für ein Schaf hin, dann bringe er zur Buße für seine Sünde dem Herrn ein Paar Turtel- oder junge Tauben, die eine als Sündopfer, die andere als Brandopfer!',
        8: 'Er bringe sie zum Priester! Und dieser bringe an erster Stelle die zum Sündopfer bestimmte dar! Er knicke ihren Kopf dicht vor dem Genick ein, ohne ihn abzutrennen!',
        9: 'Dann sprenge er von dem Blute des Sündopfers etwas an die Altarwand! Der Rest des Blutes aber werde am Altarsockel ausgepreßt! Ein Sündopfer ist es.',
        10: 'Die zweite soll er nach Gebühr fürs Brandopfer herrichten! So entsühne ihn der Priester von seiner Sünde, die er getan, und suche ihm Verzeihung zu erwirken!',
        11: 'Reicht sein Vermögen nicht für ein paar Turtel- oder junge Tauben hin, dann bringe er für seine Sünde nur ein Zehntel Scheffel Feinmehl als seine Sündopfergabe dar! Er soll aber kein Öl darauftun noch Weihrauch darüberstreuen! Ein Sündopfer ist es ja.',
        12: 'Er bringe es zum Priester! Der Priester nehme davon eine Handvoll als sein Brandteil und lasse es aufgehen auf dem Altar für des Herrn Mähler! Es ist ein Sündopfer!',
        13: 'So entsühne ihn der Priester wegen seiner Sünde, die er bei einem dieser Anlässe getan, und suche ihm Verzeihung zu erwirken! Dem Priester falle es zu wie das Speiseopfer!"',
        14: 'Und der Herr sprach zu Moses:',
        15: '"Wenn jemand pflichtvergessen handelt und sündigt, so bringe er als seine Buße dem Herrn vom Kleinvieh einen fehlerlosen Widder zur Buße im Wert von zwei Silberringen nach dem Ring des Heiligtums!',
        16: 'Was er am Heiligen gesündigt, muß er zahlen, und er soll ein Fünftel des Betrages darauflegen; dann gebe er es dem Priester! So soll ihn der Priester durch den Schuldopferwidder entsühnen, und er suche ihm Verzeihung zu erlangen!',
        17: 'Wenn jemand sündigt und tut, was man nach den Geboten des Herrn nicht tun darf, ist sich aber dessen nicht bewußt, dann ist er dennoch schuldig und muß seine Verschuldung tragen.',
        18: 'Er bringe zur Buße vom Kleinvieh einen fehlerlosen Widder nach deiner Schätzung zum Priester! So entsühne ihn der Priester wegen des Versehens, das er unwissentlich tat, und suche ihm Verzeihung zu erwirken!',
        19: 'Es ist ein Schuldopfer. Er hat sich an dem Herrn verschuldet." Und der Herr sprach zu Moses also. "Jemand sündigt und handelt pflichtvergessen am Herrn, wenn er seinem Volksgenossen Anvertrautes oder ein Darlehen oder einen Diebstahl ableugnet oder seinem Nächsten vorenthält oder das Verlorene findet und verhehlt, und er beschwört eine Lüge, eines von all dem, wodurch ein Mensch sündigen kann. Sündigt er so und ist schuldig, so erstatte er das von ihm Geraubte oder das von ihm Vorenthaltene oder das Anvertraute oder das Verlorene, das er gefunden, oder all das, worüber er falsch geschworen hat! Er erstatte den Betrag; dazu lege er ein Fünftel darauf! Er soll es dem Eigentümer am Tage seines Schuldopfers geben! Als seine Buße soll er dem Herrn einen fehlerlosen Widder bringen, vom Kleinvieh nach deiner Schätzung, für den Priester als Buße! So entsühne ihn der Priester vor dem Herrn und suche ihm Verzeihung zu erwirken für alles, wodurch er sich verschuldet!"',
    },
    6: {
        1: 'Und der Herr sprach zu Moses:',
        2: '"Gebiete Aaron und seinen Söhnen also: \'Dies ist die Lehre über das Brandopfer, das ist das, was hinaufkommt in seinen Brand die ganze Nacht bis zum Morgen, und das Feuer des Altars werde darauf in Brand erhalten!',
        3: 'Der Priester kleide sich in sein Linnenkleid und lege ein Linnenbeinkleid an sein Fleisch und nehme vom Altar die Asche weg, worin das Feuer das Brandopfer verzehrt hat, und lege sie neben den Altar!',
        4: 'Dann ziehe er seine Kleider aus und lege andere Kleider an und trage an einen reinen Ort die Asche vor das Lager!',
        5: 'Auf dem Altar brenne unterdessen das Feuer! Es darf nicht verlöschen. Alle Morgen entzünde der Priester darauf Holzscheite und schichte das Brandopfer darauf und lasse darauf die Fettstücke der Dankopfer aufdampfen!',
        6: 'Auf dem Altar soll stets Feuer brennen und nie verlöschen!',
        7: 'Und dies ist die Lehre über das Speiseopfer: Die Aaronssöhne sollen es vor den Herrn an die Vorderseite des Altars bringen!',
        8: 'Dann nehme einer eine Handvoll von dem Feinmehl und von dem Öl des Speiseopfers und allen Weihrauch auf dem Speiseopfer und lasse es auf dem Altar zu süßem Duft als Brandteil für den Herrn verdampfen!',
        9: 'Sein Übriges soll Aaron samt den Söhnen essen! An heiliger Stätte werde es ungesäuert gegessen. Im Vorhofe des Festgezeltes sollen sie es essen!',
        10: 'Mit Sauerteig darf es nicht gebacken werden. Als ihren Anteil an meinen Mählern habe ich es bestimmt. Hochheilig ist es, wie das Sünd- und Schuldopfer.',
        11: 'Wer von den Aaronskindern männlich ist, darf es essen. Ewige Gebühr für eure Geschlechter ist es von des Herren Mählern. Wer daran rührt, wird heilig.\'"',
        12: 'Und der Herr sprach zu Moses:',
        13: '"Dies sei Aarons und seiner Söhne Opfer, das sie dem Herrn an seinem Salbungsfesttag bringen sollen: ein Zehntel Scheffel feines Mehl als ständiges Speiseopfer, die eine Hälfte davon am Morgen, die andere am Abend.',
        14: 'Auf einer Pfanne werde es mit Öl bereitet! Du sollst es eingerührt darbringen. Als halbgebackenes Bissenspeiseopfer sollst du es dem Herrn zu süßem Dufte darbringen!',
        15: 'Auch der Priester, der an seiner Statt aus seinen Söhnen gesalbt wird, soll es bereiten! Als ewige Gebühr lasse man es für den Herrn als Ganzopfer aufdampfen!',
        16: 'Ganzopfer seien alle Priesterspeiseopfer! Sie dürfen nicht gegessen werden."',
        17: 'Und der Herr sprach zu Moses:',
        18: '"Sprich zu Aaron und zu seinen Söhnen: \'Dies ist die Lehre über das Sündopfer: An dem Orte, wo das Brandopfer geschlachtet wird, werde vor dem Herrn das Sündopfer geschlachtet! Es ist hochheilig.',
        19: 'Der Priester, der es als Sündopfer darbringt, soll es essen! An heiliger Stätte werde es gegessen, im Vorhof des Festgezeltes.',
        20: 'Wer sein Fleisch berührt, wird heilig, und spritzt etwas von seinem Blut an ein Kleid, so sollst du das Bespritzte an heiligem Ort waschen!',
        21: 'Ein irdenes Gefäß, in dem es gekocht wird, werde zerbrochen, und wird es in einem kupfernen Gefäß gekocht, so werde dies gescheuert und mit Wasser ausgespült!',
        22: 'Wer bei den Priestern männlich ist, darf davon essen. Hochheilig ist es.',
        23: 'Aber nicht gegessen werde irgendein Sündopfer, von dem ein Teil des Blutes in das Festgezelt gebracht wird, um in dem Heiligtum die Sühne zu vollziehen! Im Feuer werde es verbrannt!\'"',
    },
    7: {
        1: '"Und dies ist die Lehre über das Schuldopfer: Es ist hochheilig.',
        2: 'Am Orte, wo man das Brandopfer schlachtet, soll man auch das Schuldopfer schlachten! Sein Blut soll man an den Altar ringsum sprengen!',
        3: 'Man soll von ihm all sein Fett darbringen, den Fettschwanz und das Fett der Eingeweidedecke,',
        4: 'die beiden Nieren und das Fett daran und das der Lenden und den Leberlappen! Von den Nieren soll man es abtrennen!',
        5: 'Der Priester lasse es auf dem Altare aufdampfen als Mahl für den Herrn! Es ist ein Schuldopfer.',
        6: 'Wer bei den Priestern männlich ist, darf es essen. An heiliger Stätte soll man es verzehren! Es ist hochheilig.',
        7: 'Wie das Sündopfer, so das Schuldopfer! Ein Gesetz gilt für beide: Dem Priester, der damit die Sühne vollzieht, soll es zufallen!',
        8: 'Dem Priester, der eines anderen Brandopfer darbringt, gehöre die Haut des Brandopfers, das er darbringt! Dem Priester soll sie gehören!',
        9: 'Und jedes Speiseopfer, das im Ofen gebacken wird, und alles, was im Topf und in der Pfanne bereitet wird, soll dem Priester gehören, der es darbringt! Ihm soll es gehören!',
        10: 'Und jedes Speiseopfer, mit Öl bereitet und trocken, soll allen Aaronssöhnen gehören, einem wie dem anderen!',
        11: 'Und dies ist die Lehre über die Dankopfer, die man dem Herrn darbringt:',
        12: 'Bringt er sie als Dankopfer dar, dann bringe er zu dem Dankopfer noch ungesäuerte, mit Öl bereitete Kuchen und ungesäuerte, mit Öl bestrichene Fladen und feines Mehl zu Kuchen, mit Öl vermengt!',
        13: 'Zu Kuchen von gesäuertem Brote soll er sein Opfer bei seinem Lobdankopfer darbringen!',
        14: 'Zu jeder Art von Opfer bringe er davon je einen dar als Weihegabe für den Herrn! Dem Priester, der das Blut des Dankopfers aussprengt, soll es gehören!',
        15: 'Das Fleisch des Lobdankopfers soll am Tag seiner Darbringung gegessen werden! Man soll nichts davon bis zum Morgen hinlegen!',
        16: 'Ist seiner Opfergabe Opfer ein Gelübde oder eine freie Leistung, dann werde es am Tag der Opferung verzehrt! Den Rest davon mag man am Tag darauf essen.',
        17: 'Was vom Opferfleisch noch am dritten Tag übrig ist, werde verbrannt!',
        18: 'Wird von dem Fleisch des Dankopfers am dritten Tage gegessen, so gereicht dies dem Darbringer nicht zum Segen; ihm wird es nicht zugerechnet. Es gilt als verdorben, und wer davon genießt, muß seine Schuld tragen.',
        19: 'Das Fleisch, das irgend etwas Unreinem zu nahe kam, werde nicht gegessen! Es ist zu verbrennen. Das Fleisch sonst darf jeder Reine essen.',
        20: 'Wer Fleisch von einem Dankopfer des Herrn genießt und ist mit Unreinheit behaftet, der werde aus seinem Volke gestrichen!',
        21: 'Wer etwas Unreines berührt, sei es Unreines an einem Menschen oder an einem unreinen Tier oder ein unreines Gewürm, und ißt vom Fleisch des Dankopfers des Herrn, dieser werde aus seinem Volke gestrichen!"',
        22: 'Und der Herr redete mit Moses:',
        23: '"Sprich also zu den Söhnen Israels: \'Ihr sollt kein Fett von Rindern, Schafen und Ziegen essen!',
        24: 'Das Fett gefallener und zerrissener Tiere kann zu allerlei verwendet werden; aber essen dürft ihr es nicht.',
        25: 'Jeder, der Tierfett ißt, wie man es dem Herrn als Mahl bringt, wer davon ißt, dieser werde aus seinem Volke gestrichen!',
        26: 'Ihr sollt keinerlei Blut in irgendeiner eurer Siedlungen genießen, nicht von Vögeln und nicht von Vieh!',
        27: 'Wer irgendwie Blut genießt, soll aus seinem Volke gestrichen werden!\'"',
        28: 'Und der Herr redete zu Moses:',
        29: '"Sprich also zu den Söhnen Israels: \'Wer dem Herrn sein Dankopfer bringt, soll von seinem Dankopfer dem Herrn seine Opfergabe bringen!',
        30: 'Seine eigenen Hände sollen des Herrn Mahl darbringen! Er bringe das Fett samt der Brust! Die Brust, um sie als Gabe vor den Herrn zu bringen!',
        31: 'Der Priester lasse das Fett auf dem Altar aufdampfen! Die Brust gehöre Aaron und den Söhnen!',
        32: 'Die rechte Keule sollt ihr von euren Dankopfern dem Priester als Weihegabe geben!',
        33: 'Wer von den Aaronssöhnen Blut und Fett der Dankopfer darbringt, dem soll die rechte Keule als Anteil gehören!',
        34: 'Ich selber habe ja von den Söhnen Israels bei ihren Dankopfern die Brust der Abgabe genommen und die Keule der Weihegabe und sie dem Priester Aaron und seinen Söhnen gegeben als ewige Gebühr von seiten der Israeliten.\'"',
        35: 'Dies ist der Rechtsteil des Aaron und seiner Söhne an den Mählern des Herrn, seitdem er sie herangezogen hatte, dem Herrn Priesterdienste zu leisten,',
        36: 'hatte doch der Herr am Tage, da man sie salbte, geboten, man solle ihnen dies geben von seiten der Israeliten als ewige Gebühr für ihre Geschlechter.',
        37: 'Dies ist die Lehre über das Brandopfer, das Speiseopfer, das Sünd- und Schuldopfer, das Einsetzungsopfer und das Dankopfer,',
        38: 'die der Herr dem Moses auf dem Berg Sinai geboten, als er den Israeliten befahl, ihre Opfer dem Herrn in der Wüste Sinai darzubringen.',
    },
    8: {
        1: 'Und der Herr sprach zu Moses also:',
        2: '"Nimm Aaron und seine Söhne, die Gewänder und das Salböl, den Sündopferfarren und die beiden Widder sowie den Korb mit Ungesäuertem!',
        3: 'Versammle die ganze Gemeinschaft vor der Pforte des Festgezeltes!"',
        4: 'Da tat Moses, wie ihm der Herr befohlen. Die Gemeinschaft versammelte sich vor der Tür des Festgezeltes.',
        5: 'Da sprach Moses zur Gemeinschaft: "Dies ist es, was der Herr zu tun geboten hat."',
        6: 'Dann ließ Moses Aaron und seine Söhne herantreten und ließ sie ein Wasserbad nehmen.',
        7: 'Er legte ihm den Leibrock an, umgürtete ihn mit dem Gürtel, bekleidete ihn mit dem Obergewand, legte ihm das Schulterkleid an, band ihm die Schulterkleidbinde um und befestigte sie fest daran.',
        8: 'Dann befestigte er die Tasche daran und legte in die Tasche die Urim und Tummim.',
        9: 'Aufs Haupt setzte er ihm den Kopfbund und befestigte vorn am Kopfbund das goldene Blatt, das heilige Diadem, wie es der Herr dem Moses geboten hatte.',
        10: 'Dann nahm Moses das Salböl, salbte die Wohnung und alles darin und weihte es.',
        11: 'Davon sprengte er siebenmal auf den Altar, salbte den Altar, alle seine Geräte sowie das Becken und sein Gestell, um sie zu weihen.',
        12: 'Dann goß er vom Salböle auf Aarons Haupt und salbte ihn, um ihn zu weihen.',
        13: 'hierauf ließ Moses die Söhne Aarons herantreten, bekleidete sie mit Leibröcken, umgürtete sie mit einem Gürtel und setzte ihnen Mützen auf, wie es der Herr dem Moses befohlen.',
        14: 'Er holte dann den Sündopferfarren. Und Aaron mit seinen Söhnen legten die Hände auf den Kopf des Sündopferfarrens.',
        15: 'Moses aber schlachtete ihn, nahm das Blut und tat es mit dem Finger ringsum an die Altarhörner und entsündigte den Altar; das übrige Blut aber hatte er an den Altarsockel gegossen. So weihte er den Altar durch Vollzug der Sühnehandlungen daran.',
        16: 'Dann nahm man alles Eingeweidefett, den Leberlappen und die beiden Nieren mit ihrem Fett. Und Moses ließ es auf dem Altar aufdampfen.',
        17: 'Den Farren, seine Haut, sein Fleisch und seinen Mist hatte man außerhalb des Lagers verbrannt, wie es der Herr dem Moses befohlen hatte.',
        18: 'Dann ließ er den Brandopferwidder bringen, und Aaron mit seinen Söhnen legten die Hände auf den Widderkopf.',
        19: 'Moses schlachtete ihn und sprengte das Blut rings um den Altar.',
        20: 'Den Widder aber hatte er in seine Rumpfstücke zerlegt. Den Kopf, die Rumpfstücke und den Schmer ließ nun Moses aufdampfen.',
        21: 'Die Eingeweide aber und die Beine hatte er mit Wasser gewaschen. Dann ließ Moses den ganzen Widder auf dem Altar aufdampfen. Ein Brandopfer von süßem Duft war es, ein Mahl für den Herrn, wie es der Herr dem Moses befohlen hatte.',
        22: 'Dann ließ er den anderen Widder bringen, den Einsetzungswidder, und Aaron mit seinen Söhnen legten die Hände auf den Widderkopf.',
        23: 'Moses schlachtete ihn, nahm von seinem Blute und tat es an Aarons rechtes Ohrläppchen, an seinen rechten Daumen und seine rechte große Zehe.',
        24: 'Dann ließ Moses die Aaronssöhne herantreten und tat vom Blute an ihr rechtes Ohrläppchen, ihren rechten Daumen und ihre rechte große Zehe. Das übrige Blut sprengte Moses ringsum an den Altar.',
        25: 'Er nahm das Fett, den Fettschwanz und alles Eingeweidefett, die Leberlappen, die beiden Nieren mit ihrem Fett und die rechte Keule.',
        26: 'Aus dem Korbe mit Ungesäuertem, der vor dem Herrn stand, hatte er einen ungesäuerten Kuchen genommen, einen mit Öl bereiteten Brotkuchen und einen Fladen; dann legte er sie zu den Fettstücken und zu der rechten Keule.',
        27: 'Dann gab er alles Aaron und seinen Söhnen in die Hände und weihte es so als Abgabe vor dem Herrn.',
        28: 'Hierauf nahm es Moses ihnen aus den Händen und ließ es auf dem Brandopferaltar aufdampfen. Ein Einsetzungsopfer von süßem Duft, ein Mahl für den Herrn war es.',
        29: 'Dann nahm Moses die Brust und brachte sie vor dem Herrn als Abgabe dar. Sie fiel vom Einsetzungswidder Moses als Anteil zu, wie es der Herr dem Moses geboten.',
        30: 'Und Moses nahm vom Salböl und vom Blute auf dem Altar und sprengte es auf Aaron, seine Gewänder, ebenso auf seine Söhne und seiner Söhne Gewänder. So weihte er Aaron und seine Gewänder, ebenso seine Söhne und seiner Söhne Gewänder.',
        31: 'Dann sprach Moses zu Aaron und seinen Söhnen: "Kocht vor des Festgezeltes Pforte das Fleisch! Dort sollt ihr es essen samt dem Brot im Korbe des Weiheopfers, wie mir geboten ward: \'Aaron soll es mit seinen Söhnen essen!\'',
        32: 'Was an Fleisch und Brot übrigbleibt, müßt ihr verbrennen!',
        33: 'Nicht weichen sollt ihr sieben Tage von des Festgezeltes Pforte bis zu dem Tage, da eure Weihezeit vorüber ist! Sieben Tage lang soll er euch weihen!',
        34: 'Wie man heute getan, so hat der Herr auch weiterhin zu tun geboten, wenn es gilt, euch zu entsühnen.',
        35: 'Sieben Tage sollt ihr an des Festgezeltes Pforte Tag und Nacht bleiben! Befolgt des Herrn Geheiß, sonst müßt ihr sterben. Denn so ist mir geboten worden."',
        36: 'Aaron und seine Söhne taten alles, was der Herr durch Moses befohlen hatte.',
    },
    9: {
        1: 'Am achten Tage berief Moses Aaron und seine Söhne sowie Israels Älteste.',
        2: 'Er sprach zu Aaron: "Nimm dir ein junges Kalb zum Sündopfer und einen Widder zum Brandopfer, beide fehlerlos, und bringe sie vor dem Herrn dar!',
        3: "Und zu den Söhnen Israels sollst du folgendes sprechen: 'Holt einen Ziegenbock für das Sündopfer! Ein Kalb und ein Schaf, beide noch nicht jährig und fehlerlos, für das Brandopfer,",
        4: 'und ein Rind mit einem Widder für das Dankopf er, zur Schlachtung vor dem Herrn, und ein mit Öl bereitetes Speiseopfer! Denn heute erscheint euch der Herr.\'"',
        5: 'Sie holten nun, was Moses verlangt hatte, zum Festgezelt, und die ganze Gemeinschaft kam und trat vor den Herrn.',
        6: 'Da sprach Moses: "Was euch der Herr befiehlt, sollt ihr tun, daß euch des Herrn Herrlichkeit erscheine!"',
        7: 'Und Moses sprach zu Aaron: "Tritt an den Altar! Besorge dein Sünd- und Brandopfer und schaffe für dich und für das Volk Sühne! Dann besorge des Volkes Opfergabe und schaffe ihnen Sühne, wie der Herr befohlen hat!"',
        8: 'Und Aaron trat an den Altar und schlachtete das Sündopferkalb für sich selbst.',
        9: 'Und Aarons Söhne reichten ihm das Blut. Er tauchte seinen Finger ins Blut und tat es an die Altarhörner. Das übrige Blut aber hatte er an den Altarsockel gegossen.',
        10: 'Das Fett, die Nieren, die Leberlappen vom Sündopfer hatte er auf dem Altar aufdampfen lassen, wie der Herr dem Moses geboten.',
        11: 'Das Fleisch aber und die Haut hatte er außerhalb des Lagers verbrennen lassen.',
        12: 'Dann schlachtete er das Brandopfer. Die Aaronssöhne reichten ihm das Blut, und er sprengte es ringsum an den Altar.',
        13: 'Das Brandopfer reichten sie ihm in Stücken samt dem Kopfe. Er ließ es auf dem Altar aufdampfen.',
        14: 'Die Eingeweide und die Beine wusch er mit Wasser und ließ sie zu dem Brandopfer hin auf dem Altar aufdampfen.',
        15: 'Dann brachte er das Opfer des Volkes dar. Er nahm den Sündopferbock, der für das Volk war, schlachtete ihn und brachte ihn als Sündopfer dar wie den ersten.',
        16: 'Dann brachte er das Brandopfer dar und machte es nach Vorschrift.',
        17: 'Hierauf brachte er das Speiseopfer dar. Er nahm davon eine Handvoll und ließ es auf dem Altar aufdampfen, außer dem Morgenbrandopfer.',
        18: 'Dann schlachtete er das Rind und den Widder als Dankopfer für das Volk. Die Aaronssöhne reichten ihm das Blut, und er sprengte es ringsum an den Altar.',
        19: 'Des Rindes Fettstücke und die des Widders, den Fettschwanz, die Decke, die Nieren und den Leberlappen,',
        20: 'die Fettstücke legten sie auf die Bruststücke. Dann ließ er die Fettstücke auf dem Altar aufdampfen.',
        21: 'Die Bruststücke aber und die rechte Keule brachte Aaron als Abgabe vor dem Herrn dar, wie es Moses befohlen hatte.',
        22: 'Dann streckte Aaron die Hand über das Volk und segnete es. Nach Vollzug des Sünd-, des Brand- und des Dankopfers stieg er herab.',
        23: 'Moses und Aaron traten nun ins Festgezelt. Dann gingen sie hinaus und segneten das Volk. Da erschien des Herrn Majestät dem ganzen Volk.',
        24: 'Feuer aber ging vom Herrn aus und verzehrte auf dem Altar das Brandopfer und die Fettstücke. Alles Volk sah es. Sie jubelten und fielen dabei auf ihr Angesicht.',
    },
    10: {
        1: 'Die Aaronssöhne Nadab und Abihu aber nahmen ein jeder seine Kohlenpfanne, taten Feuer hinein, legten Weihrauch darauf und brachten vor den Herrn ein ungehöriges Feuer, das er ihnen nicht geboten hatte.',
        2: 'Da ging Feuer von dem Herrn aus und verzehrte sie. So starben sie vor dem Herrn.',
        3: 'Da sprach Moses zu Aaron: "Dies ist es, was der Herr sagen will: \'An denen, die mir nahestehen, zeige ich mich als heilig und als herrlich vor dem ganzen Volke.\'" Aaron aber schwieg.',
        4: 'Da rief Moses nach Misael und Elsaphan, den Söhnen Uziels, des Oheims von Aaron, und sprach zu ihnen: "Kommt her und tragt eure Brüder fort vom Heiligtum hinaus vor das Lager!"',
        5: 'Da kamen sie her und trugen sie in ihren Leibröcken vor das Lager, wie Moses gesagt hatte.',
        6: 'Und Moses sprach zu Aaron, Eleazar und Itamar, seinen Söhnen: "Löst nicht euer Haupthaar! Zerreißt nicht eure Kleider, daß ihr nicht sterbet! Er würde über die ganze Gemeinschaft ergrimmen, wenn eure Brüder, das ganze Haus Israels, den Brand beweinten, den der Herr gemacht.',
        7: 'Weicht nicht von der Pforte des Festgezeltes, daß ihr nicht sterbet! Das Salböl des Herrn ist an euch." Sie aber taten nach dem Wort des Herrn.',
        8: 'Da sprach der Herr zu Aaron:',
        9: '"Trink weder Wein noch Bier, weder du noch deine Söhne, wenn ihr das Festgezelt betretet, daß ihr nicht sterbet! Für eure Geschlechter sei es ewig geltende Vorschrift!',
        10: 'Unterscheidet zwischen Heiligem und Nichtheiligem, Unreinem und Reinem!',
        11: 'Unterweiset die Israeliten in all den Gesetzen, die ihnen der Herr durch Moses verkündet hat!"',
        12: 'Und Moses sprach zu Aaron, Eleazar und Itamar, seinen übriggebliebenen Söhnen: "Nehmt das Speiseopfer, das von des Herrn Mählern übrig ist, und esset es ungesäuert neben dem Altar! Es ist hochheilig.',
        13: 'Eßt es an heiliger Stätte! Es ist die Gebühr, die dir mit deinen Söhnen von des Herrn Mählern zufällt. So ist es mir geboten worden.',
        14: 'Der Abgabe Brust sowie der Weihegabe Keule sollt ihr an reinem Orte essen, du, deine Söhne und deine Töchter! Sie sollen dir und deinen Söhnen von den Dankopfern der Israeliten als Gebühr zufallen!',
        15: 'Der Weihegabe Keule und die Brust der Abgabe soll man zu den Mählern der Fettstücke bringen, um sie vor dem Herrn darzubringen! Sie sollen dir und deinen Söhnen, wie der Herr befohlen, als ewige Gebühr zufallen!"',
        16: 'Moses aber hatte besorgt nach dem Sündopferbock gefragt. Da war er schon verbrannt. Daraufhin zürnte er auf Eleazar und Itamar, Aarons Söhne, und sprach:',
        17: '"Warum habt ihr das Sündopfer nicht an heiliger Stätte gegessen? Hochheilig ist es ja. Er hat es euch gegeben, um die Schuld der Gemeinschaft wegzunehmen und für sie vor dem Herrn Sühne zu erwirken.',
        18: 'Ist doch sein Blut nicht in das Innere des Heiligtums hineingebracht worden! Darum mußtet ihr es im Heiligtum ganz verzehren, wie es mir geboten ward."',
        19: 'Da sprach Aaron zu Moses: "Sie haben heute ihr Sünd- und Brandopfer vor dem Herrn dargebracht, und doch traf mich solches. Hätte ich heute ein Sündopfer verzehrt, gefiele dies dem Herrn?"',
        20: 'Dies hörte Moses, und es war recht vor seinen Augen.',
    },
    11: {
        1: 'Der Herr redete mit Moses und Aaron und sagte zu ihnen folgendes:',
        2: '"Sprecht zu den Söhnen Israels: \'Dies sind die Tiere, die ihr essen dürft von allem Vieh auf Erden:',
        3: 'Was gespaltene Klauen hat, ganz durchgespaltene, und was wiederkäut, das dürft ihr essen.',
        4: 'Dagegen dürft ihr von den Wiederkäuern nicht die genießen, die gespaltene Klauen haben: das Kamel; denn es hat, wenn auch Wiederkäuer, doch keine ganz gespaltenen Klauen. Unrein sei es euch!',
        5: 'Auch nicht den Klippdachs; denn er hat, obschon Wiederkäuer, keine ganz gespaltenen Klauen. Unrein sei er euch!',
        6: 'Auch nicht den Hasen; denn er hat, obschon Wiederkäuer, keine ganz gespaltenen Klauen. Unrein sei er euch!',
        7: 'Auch nicht das Schwein! Es hat zwar ganz gespaltene Klauen, ist aber kein Wiederkäuer. Unrein sei es euch!',
        8: 'Ihr dürft ihr Fleisch nicht essen und ihr Aas nicht berühren. Sie seien euch unrein!',
        9: 'Von allem, was im Wasser ist, dürft ihr dies verzehren: Was im Gewässer, in den Meeren und in Bächen Flossen und Schuppen hat, dürft ihr essen.',
        10: 'Was aber im Meer und in den Bächen weder Flossen noch Schuppen hat von allem, was im Wasser wimmelt, von allen Lebewesen, die im Wasser sind, sei euch ein Greuel!',
        11: 'Sie seien euch ein Greuel! Von ihrem Fleische dürft ihr nichts genießen. Ihr Aas müßt ihr verabscheuen.',
        12: 'Greuel sei euch, was im Wasser keine Flossen und keine Schuppen hat.',
        13: 'Und von den Vögeln sollt ihr folgende verabscheuen! Sie dürfen, als Greuel, nicht gegessen werden: Adler, Bartgeier und Geier,',
        14: 'Weihe und Falken, je in ihrer Art,',
        15: 'alle Raben, je in ihrer Art;',
        16: 'Strauß, Schwalbe, Möve, Habicht, je in ihrer Art,',
        17: 'Käuzchen und Sturzpelikan, Uhu,',
        18: 'Eule und Pelikan, Erdgeier,',
        19: 'Storch, Regenpfeifer, je in ihrer Art, Wiedehopf, Fledermaus.',
        20: 'Und alles geflügelte Gewimmel, das auf Vieren geht, sei euch ein Greuel!',
        21: 'Von allem geflügelten Gewimmel, das auf Vieren geht, dürft ihr nur die verzehren, die über ihren Füßen ein Schenkelpaar haben, um damit auf der Erde zu hüpfen.',
        22: 'Von diesen dürft ihr folgende verzehren: Die Heuschrecke in ihrer Art, die Freßheuschrecke in ihrer Art, das Heupferd in seiner Art, die Springheuschrecke in ihrer Art.',
        23: 'Die anderen kleinen Flügeltiere, die vier Füße haben, seien euch ein Greuel!',
        24: 'Durch folgendes könnt ihr euch unrein machen: Wer ihr Aas berührt, bleibt bis zum Abend unrein.',
        25: 'Wer eines ihrer Äser trägt, soll seine Kleider waschen! Er bleibt bis zum Abend unrein.',
        26: 'Jedes Tier, das Klauen hat, die zwar gespalten, aber nicht ganz durchgespalten sind, und das nicht wiederkäut, gelte euch als unrein! Wer es berührt, wird unrein.',
        27: 'Alles, was auf Tatzen geht, sei euch von allen Vierfüßlern unrein! Wer ihr Aas berührt, bleibt bis zum Abend unrein.',
        28: 'Wer ihr Aas anfaßt, wasche seine Kleider! Er bleibt bis zum Abend unrein. Sie seien euch unrein!',
        29: 'Die für euch unrein sind, sind folgende von dem Gewimmel, das auf Erden wimmelt: das Wiesel, die Maus und die Eidechsen in ihrer Art,',
        30: 'die Spitzmaus, das Chamäleon, der Gecko, die Eidechse und der Salamander.',
        31: 'Diese seien euch von allem Gewimmel unrein! Wer sie in ihrem Tod berührt, sei bis zum Abend unrein!',
        32: 'Alles das, worauf von ihnen eines im Tode fällt, wird unrein. Alles Holzgerät oder Gewand oder Fell oder Tuch, all die Gefäße, die zum Gebrauch dienen. Ins Wasser werde es verbracht! Es bleibt bis zum Abend unrein. Dann ist es wieder rein.',
        33: 'Fällt davon eines in ein irdenes Gefäß, so wird alles, was darin ist, unrein. Ihr müßt es zerschlagen.',
        34: 'Alle Speise, an die zum Genießen Wasser kommt, wird unrein, und alles trinkbare Getränk wird in jedem Gefäß unrein.',
        35: 'Alles, worauf eines ihrer Äser fällt, wird unrein. Backofen und Kochherd müssen abgebrochen werden, wenn sie unrein sind. Auch sie seien euch unrein!',
        36: 'Nur Quellen, Brunnen und Wasserbecken bleiben rein. Nur wer ihr Aas berührt, wird unrein.',
        37: 'Fällt eines ihrer Äser auf irgendeinen Samen einer Aussaat, die man säen will, so bleibt er rein.',
        38: 'Bringt man aber Wasser an den Samen und eines ihrer Äser fällt darauf, so sei er euch unrein!',
        39: 'Fällt ein Stück von dem Vieh, das euch zum Essen dient, dann wird bis zum Abend unrein, wer sein Aas berührt.',
        40: 'Und wer von seinem Aase ißt, soll seine Kleider waschen! Er bleibt bis zum Abend unrein. Wer sein Aas anfaßt, soll seine Kleider waschen! Er bleibt bis zum Abend unrein.',
        41: 'All das Gewimmel, das auf Erden wimmelt, ist als Greuel nicht genießbar.',
        42: 'Was auf dem Bauche kriecht und was auf Vieren geht, bis zu allem Vierfüßigen, von allem Gewimmel, das auf Erden wimmelt, eßt sie nicht! Sie sind ein Greuel.',
        43: 'Ihr sollt euch nicht selbst durch irgendein Kriechtier abscheulich machen! Verunreinigt euch nicht durch sie, daß ihr dadurch unrein würdet!',
        44: 'Denn ich, der Herr, bin euer Gott. Nun, so zeigt euch als heilig und seid heilig! Denn ich bin heilig. Ihr sollt euch nicht selbst durch irgendein Gewimmel verunreinigen, das auf Erden wimmelt!',
        45: 'Ich bin der Herr, der euch aus Ägypterland geführt, um euch Gott zu sein. So werdet heilig! Denn ich bin heilig.',
        46: 'Dies ist die Lehre über das Vieh, das Geflügel und alle Lebewesen, die im Wasser tummeln und alle Wesen, die auf Erden wimmeln,',
        47: 'damit man scheide zwischen Unreinem und Reinem und zwischen eßbaren Lebewesen und ungenießbaren Lebewesen.\'"',
    },
    12: {
        1: 'Der Herr sprach zu Moses also:',
        2: '"Sprich zu den Söhnen Israels: \'Schenkt ein Weib einem Knaben im Wochenbett das Leben, so ist sie sieben Tage unrein, so wie sie in den Tagen ihrer monatlichen Unreinheit unrein ist.',
        3: 'Am achten Tage werde seines Gliedes Fleisch beschnitten!',
        4: 'Dreiunddreißig Tage soll sie im Reinigungsblute bleiben! Sie darf nichts Heiliges berühren und darf nicht in das Heiligtum kommen, bis daß die Tage ihrer Reinigung vorüber sind!',
        5: 'Schenkt sie aber einem Mädchen das Leben, so sei sie zwei Wochen unrein wie bei ihrer monatlichen Unreinheit, und sechsundsechzig Tage soll sie im Reinigungsblute bleiben!',
        6: 'Sind die Tage ihrer Reinigung vorüber bei einem Sohn oder einer Tochter, so soll sie ein noch nicht einjähriges Lamm zum Brandopfer bringen und eine junge Taube oder eine Turteltaube zum Sündopfer an des Festgezeltes Pforte zu dem Priester!',
        7: 'Er bringe sie vor dem Herrn dar und schaffe ihr Sühne! So werde sie rein von ihrem Blutflusse! Dies ist die Lehre über Kindbetterinnen, sei es bei Knaben oder Mädchen.',
        8: "Reicht aber ihr Vermögen nicht für ein Schaf hin, so nehme sie zwei Turteltauben oder sonst zwei junge Tauben, die eine für das Brandopfer, die andere für das Sündopfer, und so verschaffe ihr der Priester Sühne, daß sie rein werde!'",
    },
    13: {
        1: 'Der Herr sprach zu Moses und Aaron also:',
        2: '"Zeigt sich auf jemandes Haut ein Mal oder ein Grind oder ein Fleck und bildet sich auf seiner Haut ein Aussatzschaden, dann bringe man ihn vor den Priester Aaron oder einen seiner Priestersöhne!',
        3: 'Sieht nun der Priester den Schaden an der Haut und ist das Haar in dem Schaden weiß geworden und ist der Schein des Schadens tiefer als die Haut seines Fleisches, so ist es Aussatzschaden. Sieht dies der Priester, dann erkläre er ihn für unrein!',
        4: 'Ist ein weißer Fleck an der Haut seines Fleisches und ist sein Schein nicht tiefer als die Haut und ist das Haar daran nicht weiß geworden, dann sondere der Priester sieben Tage den Schaden ab!',
        5: 'Beschaut ihn der Priester am siebten Tage und blieb der Schaden bei seiner Farbe, griff der Schaden auf der Haut nicht weiter um sich, dann sondere der Priester weitere sieben Tage den Schaden ab!',
        6: 'Beschaut ihn der Priester abermals am siebten Tage und wurde der Schaden blässer und griff der Schaden auf der Haut nicht weiter um sich, dann erkläre ihn der Priester für rein! Ein Grind ist es. Er wasche seine Kleider! Dann ist er rein.',
        7: 'Greift aber auf der Haut der Grind immer weiter um sich, nachdem er vom Priester zu seiner Reinsprechung beschaut war, und zeigt er sich abermals dem Priester',
        8: 'und sieht der Priester, daß auf der Haut der Grind um sich griff, dann erkläre der Priester ihn für unrein! Aussatz ist es.',
        9: 'Ist an einem Menschen ein Aussatzschaden, so bringe man diesen Fall vor den Priester!',
        10: 'Sieht der Priester, daß ein weißes Mal an der Haut ist, und das Haar daran ist weiß geworden und in dem Mal wuchert wildes Fleisch,',
        11: 'dann ist an der Haut seines Fleisches ein unheilbarer Aussatz. Der Priester erkläre ihn für unrein! Er soll ihn aber nicht absondern! Er ist unrein.',
        12: 'Blüht aber der Aussatz auf der Haut und bedeckt der Aussatz vom Kopf bis zu den Füßen die ganze Schadenhaut im ganzen Schaubereich des Priesters',
        13: 'und sieht der Priester, daß der Aussatz seinen ganzen Leib bedeckt, dann erkläre er den Schaden für rein! Ganz weiß geworden, ist er rein.',
        14: 'Wenn sich aber wildes Fleisch an ihm zeigt, dann wird er unrein.',
        15: 'Und sieht der Priester das wilde Fleisch, dann erkläre er ihn für unrein! Das wilde Fleisch ist unrein. Aussatz ist es.',
        16: 'Verschwindet freilich das wilde Fleisch und er wird weiß und kam er zum Priester',
        17: 'und besah ihn der Priester und wurde der Schaden weiß, dann erkläre der Priester den Schaden für rein! Er ist rein.',
        18: 'Ist an der Haut ein Geschwür und heilt es wieder',
        19: 'und entsteht an Stelle des Geschwüres ein weißes Mal oder ein weißrötliches, ein Fleck, so zeige er sich dem Priester!',
        20: 'Und sieht der Priester, daß die Gestalt des Fleckes tiefer als die Haut ist, und ist daran sein Haar weiß geworden, dann erkläre ihn der Priester für unrein! Aussatzschaden ist es, im Geschwür ausgebrochen.',
        21: 'Beschaut es der Priester und kein Haar ist daran weiß geworden, auch ist es nicht tiefer als die Haut, nur blasser, dann sondere ihn der Priester sieben Tage ab!',
        22: 'Greift es dann weiter auf der Haut um sich, dann erkläre ihn der Priester für unrein! Ein Schaden ist es.',
        23: 'Bleibt aber der Fleck an der gleichen Stelle und breitet er sich nicht aus, so ist es die Narbe des Geschwürs. Dann erkläre ihn der Priester für rein!',
        24: 'Oder ist eine Brandwunde an der Haut und ist das Fleisch an der Brandwunde ein weißroter oder weißer Fleck',
        25: 'und der Priester beschaut ihn, und das Haar ist an dem Fleck weiß geworden und seine Gestalt ist tiefer als die Haut, so ist der Aussatz in der Brandwunde ausgebrochen. Der Priester erkläre ihn für unrein! Es ist der Aussatz.',
        26: 'Beschaut ihn der Priester und ist kein weißes Haar am Fleck und ist er nicht tiefer als die Haut, nur blässer, dann sondere ihn der Priester sieben Tage ab!',
        27: 'Beschaut ihn der Priester am siebten Tag, dann erkläre ihn der Priester für unrein, falls es auf seiner Haut weiter um sich griff! Dann ist es Aussatz.',
        28: 'Blieb aber der Fleck auf der gleichen Stelle und griff er nicht auf der Haut um sich und ward er nur blässer, so ist es das Mal der Brandwunde. Für rein erkläre ihn der Priester! Nur Brandwundnarbe ist es.',
        29: 'Ist bei einem Manne oder Weib ein Schaden am Kopf oder Bart',
        30: 'und der Priester beschaut den Schaden und ist er tiefer als die Haut und goldgelbes dünnes Haar daran, dann erkläre ihn der Priester für unrein! Krätze ist es, Aussatz des Kopfes oder Bartes.',
        31: 'Besichtigt der Priester den Krätzeschaden und ist er nicht tiefer als die Haut, fehlen aber schwarze Haare, dann sondere der Priester den Krätzeschaden sieben Tage ab!',
        32: 'Besichtigt der Priester am siebten Tag den Schaden und griff die Krätze nicht um sich und war darin kein goldgelbes Haar und ist die Krätze nicht tiefer als die Haut,',
        33: 'So lasse er sich scheren, aber nicht die Krätze! Dann sondere der Priester die Krätze nochmals sieben Tage ab!',
        34: 'Besichtigt am siebten Tag der Priester die Krätze und griff die Krätze nicht auf der Haut um sich und ist ihre Gestalt nicht tiefer als die Haut, so erkläre ihn der Priester für rein. Er wasche seine Kleider! Dann ist er rein.',
        35: 'Greift aber die Krätze auf der Haut um sich nach seiner Reinerklärung',
        36: 'und besichtigt ihn der Priester und hat die Krätze weiter auf der Haut um sich gegriffen, so braucht der Priester nicht nach dem goldgelben Haar zu suchen. Er ist unrein.',
        37: 'Bleibt sich aber die Krätze im Aussehen gleich und wächst schwarzes Haar daran, so ist die Krätze geheilt. Er ist rein. Für rein erkläre ihn der Priester!',
        38: 'Sind bei einem Manne oder Weibe Flecken auf der Haut, mattweiße Flecken',
        39: 'und bemerkt ein Priester, daß auf der Haut ihres Fleisches verblaßte, weiße Flecken sind, so sind es Flechten, die auf der Haut ausbrachen. Ein solcher ist rein.',
        40: 'Wird jemandes Haupt kahl und ist es ein Hinterglatzkopf, so ist er rein.',
        41: 'Wird aber vorn sein Kopf kahl, so ist es ein Vorderglatzkopf. Er ist rein.',
        42: 'Zeigt sich aber an der hinteren oder vorderen Glatze ein weißlichroter Schaden, so ist es der Aussatz, der an seiner hinteren oder vorderen Glatze ausbricht.',
        43: 'Besichtigt ihn der Priester und ist ein weißlichrotes Schadenmal an seiner hinteren oder vorderen Glatze, das aussieht wie der Aussatz auf der Haut des Fleisches,',
        44: 'so ist er ein aussätziger Mann. Er ist unrein. Der Priester soll ihn für unrein erklären! An seinem Kopfe ist sein Schaden.',
        45: 'Der Aussätzige, der den Schaden an sich hat, soll sein Gewand zerreißen und soll das Haupthaar fliegen lassen, den Bart verhüllen und rufen "Unrein! Unrein!"',
        46: 'Er bleibe die ganze Zeit, da er den Schaden hat, unrein! Er soll abgesondert wohnen! Sein Bleiben sei außerhalb des Lagers!',
        47: 'Ist an einem Tuche ein Aussatzschaden, an Woll- oder Leintuch,',
        48: 'oder an Leinen- oder Wollgewebe oder Einschlag, oder auch an Leder oder an Lederware,',
        49: 'und ist der Schaden grünlich oder rötlich am Tuch oder am Leder oder am Gewebe oder am Einschlag oder an der Lederware, so ist es Aussatzschaden. Er werde vom Priester beschaut!',
        50: 'Besichtigt der Priester den Schaden, so sondere er den Schaden sieben Tage ab!',
        51: 'Am siebten Tage beschaue er den Schaden! Hat auf dem Tuche, dem Gewebe, dem Einschlag, dem Leder oder an der Lederware der Schaden um sich gegriffen, dann ist der Schaden ein fressender Aussatz. Er ist unrein.',
        52: 'Man verbrenne das Tuch oder das Gewebe oder den Einschlag in Wolle oder Leinen oder jede Ledertasche, woran der Schaden ist! Denn fressender Aussatz ist es. Im Feuer soll es verbrannt werden!',
        53: 'Besichtigt es der Priester, und der Schaden griff nicht um sich auf dem Tuch oder Gewebe oder Einschlag oder auf irgendwelchen Ledersache,',
        54: 'dann gebiete der Priester, daß man wasche, an denen der Schaden ist, und sondere es nochmals sieben Tage ab!',
        55: 'Beschaut es dann der Priester, nachdem der Schaden gewaschen wurde, und hat sich die Farbe des Schadens nicht verändert und hat der Schaden nicht um sich gegriffen, so ist es unrein. Im Feuer sollst du es verbrennen, sei es eine Einfressung an seiner hinteren oder vorderen Seite!',
        56: 'Besieht es aber der Priester, und ist der Schaden verblaßt, nachdem man ihn gewaschen hat, so schneide man ihn aus dem Tuche oder Leder oder Aufzug oder Einschlag!',
        57: 'Erscheint er nochmals am Tuch oder Gewebe oder Einschlag oder an irgendeiner Ledersache, so ist es ein frisch ausbrechender. Du sollst im Feuer das verbrennen, woran der Schaden ist!',
        58: 'Das Tuch, das Gewebe, der Einschlag oder die Lederwaren aller Art, die du wuschest und von denen der Schaden gewichen, müssen wiederum gewaschen werden. Dann erst sind sie rein.',
        59: 'Dies ist die Lehre über den Aussatzschaden an wollenem oder linnenem Tuch oder an Gewebe oder Einschlag oder irgendeiner Ledersache, inwiefern sie für rein oder unrein zu erklären sind."',
    },
    14: {
        1: 'Und der Herr sprach zu Moses also:',
        2: '"Dies ist das Gesetz über den für aussätzig Erklärten am Tage seiner Reinigung: Man bringe seinen Fall vor den Priester!',
        3: 'Dann gehe der Priester vor das Lager! Beschaut es der Priester und ist der Aussatzschaden am Aussätzigen geheilt,',
        4: 'dann gebiete der Priester, daß man für den zu Reinigenden zwei lebende, reine Vögel und Zedernholz und Karmesinwolle und Ysop hole!',
        5: 'Dann gebiete der Priester, daß man den einen Vogel in ein Tongefäß über frischem Wasser schlachte!',
        6: 'Den anderen lebendigen Vogel soll er nehmen und das Zedernholz, die Karmesinwolle und den Ysop und tauche sie und den lebendigen Vogel ins Blut des über frischem Wasser abgeschlachteten Vogels.',
        7: 'Dann besprenge er den vom Aussatz zu Reinigenden siebenmal und reinige ihn so! Den lebenden Vogel aber lasse er aufs freie Feld!',
        8: 'Dann wasche der sich zu Reinigende seine Kleider und schere sein ganzes Haar und bade sich, so wird er rein. Danach darf er ins Lager kommen, bleibe aber noch sieben Tage vor seinem Zelte!',
        9: 'Am siebten Tage soll er all sein Haar scheren, seinen Kopf und seinen Bart und seine Augenbrauen! All sein Haar soll er scheren! Dann wasche er seine Kleider und bade seinen Leib! So wird er rein.',
        10: 'Am achten Tage soll er zwei fehlerlose Lämmer nehmen und ein noch nicht einjähriges, fehlerloses, weibliches Lamm sowie drei Zehntel feines Mehl, mit Öl bereitet, für das Speiseopfer und eine Kanne Öl!',
        11: 'Der Priester, der reinigt, stelle den Mann, der sich reinigen läßt, und diese Sachen vor den Herrn an des Festgezeltes Tür!',
        12: 'Dann nehme der Priester das eine Lamm und bringe es als Schuldopfer mit der Kanne Öl dar und weihe beides vor dem Herrn!',
        13: 'Und er schlachte an dem Orte, wo das Sünd- und Brandopfer geschlachtet wird, das Lamm an heiliger Stätte! Dem Priester gehöre das Schuldopfer wie das Sündopfer! Es ist hochheilig.',
        14: 'Dann nehme der Priester vom Blut des Schuldopfers! Der Priester streiche es dem zu Reinigenden an das rechte Ohrläppchen, an den Daumen seiner rechten Hand und an die große Zehe seines rechten Fußes!',
        15: 'Dann nehme der Priester aus der Kanne etwas Öl und gieße es in die priesterliche Linke!',
        16: 'Dann tauche der Priester seinen rechten Finger in das Öl in seiner Linken und sprenge vor dem Herrn vom Öl mit seinem Finger siebenmal!',
        17: 'Vom Öl, das auf seiner Hand noch übrigbleibt, soll der Priester dem zu Reinigenden etwas an das rechte Ohrläppchen und an den Daumen seiner rechten Hand streichen und an die große Zehe seines rechten Fußes oben auf das Blut des Schuldopfers!',
        18: 'Was dann noch übrig ist von dem Öle auf der Hand des Priesters, soll er auf das Haupt des zu Reinigenden tun! So schaffe ihm der Priester vor dem Herrn Sühne!',
        19: 'Dann richte der Priester das Sündopfer her und schaffe so Sühne dem zu Reinigenden wegen seiner Unreinheit! Danach soll er das Brandopfer schlachten!',
        20: 'Dann bringe der Priester auf dem Altar das Brand- und das Speiseopfer dar! Schafft ihm so der Priester Sühne, dann wird er rein.',
        21: 'Ist er aber arm und unvermöglich, dann nehme er ein Lamm als Schuldopfer zur Darbringung und Sühneschaffung sowie ein Zehntel feines Mehl, mit Öl bereitet, mit einer Kanne Öl für das Speiseopfer',
        22: 'Sowie zwei Turtel- oder ein Paar junge Tauben, wie er es eben vermag! Die eine sei Sündopfer, die andere Brandopfer!',
        23: 'Er bringe sie am achten Tage nach seiner Reinigung zum Priester an des Festgezeltes Tür vor den Herrn!',
        24: 'Der Priester nehme mit der Kanne Öl das Lamm des Schuldopfers! Dann bringe der Priester sie vor dem Herrn als Abgabe dar!',
        25: 'Dann schlachte man das Lamm des Schuldopfers! Der Priester nehme vom Blut des Schuldopfers und streiche es dem zu Reinigenden an das rechte Ohrläppchen und an den Daumen seiner rechten Hand und an die große Zehe seines rechten Fußes!',
        26: 'Von dem Öle soll der Priester etwas in die priesterliche Linke gießen!',
        27: 'Dann sprenge der Priester mit seinem rechten Finger etwas von dem Öl in seiner Linken vor den Herrn siebenmal!',
        28: 'Dann tue der Priester etwas von dem Öl in seiner Hand an des zu Reinigenden rechtes Ohrläppchen und an den Daumen seiner Rechten und an die große Zehe seines rechten Fußes, wo sich das Blut des Schuldopfers befindet!',
        29: 'Was vom Öl auf des Priesters Hand noch übrig ist, soll er an des zu Reinigenden Kopf tun! So schaffe er ihm vor dem Herrn Sühne!',
        30: 'Dann richte er von den Turteltauben oder jungen Tauben, die er sich leisten kann,',
        31: 'die eine als Sündopfer her, die andere als Brandopfer samt dem Speiseopfer! So schaffe der Priester dem zu Reinigenden Sühne vor dem Herrn!',
        32: 'Das ist die Weisung für den, der den Aussatzschaden hat und der bei seiner Reinigung unvermöglich ist."',
        33: 'Und der Herr redete mit Moses und Aaron also:',
        34: '"Kommt ihr in das Kanaaniterland, das ich euch zu eigen gebe, und schlage ich mit dem Aussatzschaden ein Haus in eurem eigenen Lande,',
        35: "so komme der Hausbesitzer und melde es dem Priester mit den Worten: 'Wie ein Schaden dünkt es mir am Hause!'",
        36: 'Da gebiete der Priester, das Haus zu räumen, bevor der Priester kommt, den Schaden zu besichtigen, damit nicht alles im Haus unrein werde! Dann soll der Priester kommen, das Haus zu besichtigen!',
        37: 'Besichtigt er den Schaden und ist an den Hauswänden der Schaden in Gestalt von grünen oder roten Grübchen, die tiefer als die Wand zu liegen scheinen,',
        38: 'dann gehe der Priester aus dem Haus an die Haustür und verschließe auf sieben Tage das Haus!',
        39: 'Kommt der Priester am siebten Tag wieder und sieht er, daß der Schaden an den Hauswänden weiter um sich griff,',
        40: 'dann gebiete der Priester, daß man die Steine, an denen der Schaden ist, ausbreche und draußen vor der Stadt an einen unreinen Ort werfe!',
        41: 'Dann lasse er das Haus ringsum inwendig abkratzen, und draußen vor der Stadt schütte man den abgekratzten Lehm an einen unreinen Ort!',
        42: 'Dann nehme man andere Steine und bringe sie an den Platz jener Steine! Dann soll man anderen Lehm nehmen und das Haus tünchen!',
        43: 'Kehrt der Schaden am Haus wieder, nachdem jene Steine weggenommen und das abgekratzte Haus getüncht,',
        44: 'dann komme der Priester, und sieht er, daß im Haus der Schaden weiter um sich griff, so ist ein fressender Aussatz am Haus. Es ist unrein.',
        45: 'Man schleife das Haus mit seinen Steinen und Balken und den gesamten Lehm des Hauses und bringe es hinaus vor die Stadt an einen unreinen Ort!',
        46: 'Wer das verschlossene Haus betreten hat, gelte bis zum Abend für unrein!',
        47: 'Wer im Haus geschlafen hat, der soll seine Kleider waschen! Wer im Haus gegessen hat, der soll seine Kleider waschen!',
        48: 'Kommt der Priester und besichtigt es und hat der Schaden im Haus nicht um sich gegriffen nach dem Tünchen des Hauses, dann erkläre der Priester das Haus für rein! Der Schaden ist geheilt.',
        49: 'Zwei Vögel nehme er zur Entsündigung des Hauses und Zedernholz und Karmesinwolle mit Ysop!',
        50: 'Dann schlachte er den einen Vogel in ein Tongefäß über frischem Wasser',
        51: 'und nehme das Zedernholz, den Ysop, die Karmesinwolle und den lebenden Vogel, tauche sie in das Blut des geschlachteten Vogels und in das frische Wasser und besprenge siebenmal das Haus!',
        52: 'So entsündigt er das Haus mit Vogelblut und frischem Wasser, mit dem lebenden Vogel, dem Zedernholz, dem Ysop und der Karmesinwolle!',
        53: 'Dann lasse er den lebenden Vogel vor die Stadt ins freie Feld entkommen! So schaffe er dem Hause Sühne! Dann ist es rein.',
        54: 'Das ist die Weisung für die verschiedenen Arten des Aussatzschadens und der Krätze,',
        55: 'des Aussatzes an Tüchern und Häusern,',
        56: 'der Hautmale, des Schorfes und der Flecken,',
        57: 'um danach zwischen Rein oder Unrein zu entscheiden. Dies ist das Gesetz über den Aussatz."',
    },
    15: {
        1: 'Und der Herr sprach zu Moses und Aaron also:',
        2: '"Redet mit den Söhnen Israels und sprecht zu ihnen: Wer einen Fluß an seinem Fleische hat, dessen Ausfluß ist unrein.',
        3: 'Dies ist eine Unreinheit durch seinen Fluß: Mag sein Fleisch seinen Fluß ausscheiden oder mag sein Fleisch so verstopft sein, daß nichts fließt, bei ihm ist es Unreinheit.',
        4: 'Das ganze Lager, auf dem der Flüssige liegt, ist unrein, ebenso alles Gerät, auf dem er sitzt.',
        5: 'Wer sein Lager anrührt, soll seine Kleider waschen, dann bade er sich! Er bleibt bis zum Abend unrein.',
        6: 'Wer sich auf das Gerät setzt, auf dem der Flüssige saß, soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.',
        7: 'Wer das Fleisch des Flüssigen berührt, soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.',
        8: 'Speit der Flüssige auf den Reinen, so wasche dieser seine Kleider und bade sich! Er bleibt bis zum Abend unrein.',
        9: 'Alles Reitzeug, auf dem der Flüssige reitet, ist unrein.',
        10: 'Wer etwas, was unter ihm war, anrührt, bleibt bis zum Abend unrein. Wer es fortträgt, soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.',
        11: 'Wen der Flüssige mit ungewaschenen Händen berührt, der wasche seine Kleider und bade sich! Er bleibt bis zum Abend unrein.',
        12: 'Ein Tongefäß, das der Flüssige berührt, werde zerbrochen und alles Holzgerät mit Wasser abgespült!',
        13: 'Wird der Flüssige rein von seinem Fluß, dann zähle er von seinem Reinwerden sieben Tage! Dann wasche er seine Kleider und bade sein Fleisch in frischem Wasser! Dann ist er rein.',
        14: 'Am achten Tage soll er zwei Turtel- oder junge Tauben nehmen; dann komme er an des Festgezeltes Pforte vor den Herrn und gebe sie dem Priester!',
        15: 'Der Priester richte sie her, die eine als Sündopfer, die andere als Brandopfer! So schaffe ihm der Priester wegen seines Flusses Sühne vor dem Herrn!',
        16: 'Entgeht einem Mann der Same, so bade er seinen ganzen Leib! Er bleibt bis zum Abend unrein!',
        17: 'Und jedes Tuch und jedes Lederzeug, an die Samen kommt, werde gewaschen! Bis zum Abend bleibt es unrein.',
        18: 'Und schläft jemand bei einem Weibe, daß Samenfluß erfolgt, so müssen sie sich baden und sind bis zum Abend unrein.',
        19: 'Wird ein Weib durch seines Leibes Blutfluß flüssig, so haftet sieben Tage an ihr die Unreinheit. Wer sie berührt, wird bis zum Abend unrein.',
        20: 'Alles, worauf sie während ihrer Unreinheit liegt, und alles, worauf sie sitzt, wird unrein.',
        21: 'Wer ihr Lager anrührt, der soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.',
        22: 'Wer irgendein Gerät berührt, auf dem sie saß, der soll seine Kleider waschen; dann bade er sich! Er bleibt bis zum Abend unrein.',
        23: 'Wer auf dem Lager oder dem Gerät, auf dem sie saß, etwas berührt, wird bis zum Abend unrein.',
        24: 'Wenn einer bei ihr liegt, kommt er in ihre Unreinheit und bleibt sieben Tage unrein. Das ganze Lager, auf dem er liegt, wird unrein.',
        25: 'Fließt eines Weibes Blutfluß viele Tage außer der Zeit ihrer gewöhnlichen Unreinheit, oder wenn sie über ihre Unreinheit hinaus noch flüssig bleibt, so gelten alle Tage des Flusses ihrer Unreinheit als Tage ihrer Unreinheit. Sie ist unrein.',
        26: 'Das ganze Lager, auf dem sie alle Tage ihres Flusses sitzt, gelte ihr wie das Lager ihrer gewöhnlichen Unreinheit, und alles Gerät, auf dem sie sitzt, wird unrein, wie bei ihrer gewöhnlichen Unreinheit.',
        27: 'Und unrein wird jeder, der diese Dinge berührt. Er wasche seine Kleider und bade sich! Er bleibt bis zum Abend unrein.',
        28: 'Ist sie aber von ihrem Flusse rein geworden, so zähle sie noch sieben Tage! Dann ist sie rein.',
        29: 'Am achten Tage soll sie zwei Turtel- oder junge Tauben nehmen; dann bringe sie diese zum Priester an des Festgezeltes Pforte!',
        30: 'Der Priester richte die eine als Sündopfer her, die andere als Brandopfer! Und so verschaffe der Priester ihr vor dem Herrn Sühne, des Flusses wegen, der sie unrein machte!',
        31: 'Ihr sollt die Söhne Israels ob ihrer Unreinheit verwarnen, auf daß sie nicht durch ihre Unreinheit sterben, indem sie meine Wohnung in ihrer Mitte unrein machen!',
        32: 'Das ist das Gesetz über den Flüssigen und den, dem der Same entgeht, wodurch er unrein wird,',
        33: 'und über die, die an ihrer Unreinigkeit leidet, und über den, der seinen Fluß hat, über Männer wie über Weiber, und über den, der bei einer Unreinen liegt.\'"',
    },
    16: {
        1: 'Und der Herr redete zu Moses nach dem Tode der beiden Aaronssöhne, als sie dem Herrn zu nahe traten und sterben mußten.',
        2: 'Der Herr sprach zu Moses: "Sag deinem Bruder Aaron, er dürfe nicht zu jeder Zeit ins Heiligtum und hinter den Vorhang vor der Lade Deckplatte kommen, sonst müsse er sterben! Denn in der Wolke erscheine ich über der Deckplatte.',
        3: 'Nur so soll Aaron ins Heiligtum kommen, daß er einen jungen Stier als Sündopfer darbringt und einen Widder als Brandopfer!',
        4: 'Er soll einen heiligen Linnenleibrock anziehen! Über seinem Fleisch sollen linnene Beinkleider sein! Er soll sich mit einem Linnengürtel gürten und einen Linnenkopfbund umbinden! Dies sind heilige Gewänder. Darum wasche er sein Fleisch! Dann ziehe er sie an!',
        5: 'Und von der israelitischen Gemeinschaft soll er zwei Ziegenböcke zum Sündopfer nehmen und einen Widder zum Brandopfer!',
        6: 'Alsdann hole Aaron seinen Sündopferfarren und schaffe so sich und seinem Hause Sühne!',
        7: 'Dann nehme er die beiden Böcke und stelle sie an des Festgezeltes Tür vor den Herrn!',
        8: 'Und Aaron lege die Lose auf die beiden Böcke! Ein Los gelte für den Herrn, ein Los für Azazel!',
        9: "Dann nehme Aaron jenen Bock, auf den das Los gefallen 'Für den Herrn', und bereite ihn als Sündopfer!",
        10: "Den Bock, auf den das Los gefallen 'Für Azazel', soll er lebend vor den Herrn stellen, um an ihm die Sühne zu vollziehen und ihn dem Azazel in die Wüste zuzuschicken!",
        11: 'Aaron bringe seinen Sündopferfarren her und schaffe sich und seinem Hause Sühne! Er schlachte seinen Sündopferfarren!',
        12: 'Dann nehme er die Pfanne voller Feuerkohlen vom Altare vor dem Herrn weg und zwei Hände feines, würziges Räucherwerk und bringe es hinter jenen Vorhang!',
        13: 'Dann tue er das Räucherwerk aufs Feuer vor dem Herrn und hülle mit der Räucherwerkwolke die Deckplatte auf dem Zeugnis ein, daß er nicht sterbe!',
        14: 'Dann nehme er vom Farrenblut und sprenge es mit seinem Finger an die Vorderseite der Deckplatte! Vor die Deckplatte soll er siebenmal von dem Blute mit seinem Finger sprengen!',
        15: 'Dann schlachte er des Volkes Sündopferbock und bringe sein Blut hinter jenen Vorhang und tue mit seinem Blute so wie mit dem Farrenblut und sprenge es auf die Deckplatte und vor sie hin!',
        16: 'So entsündige er das Heiligtum, wegen der Unreinheiten der Söhne Israels und wegen ihrer Frevel bei all ihren Sünden. So soll er mit dem Festgezelte dessen tun, der bei ihnen wohnt inmitten ihrer Unreinheit!',
        17: 'Im Festgezelt darf aber niemand sein, wenn er kommt, im Heiligtum die Sühnebräuche zu tun, bis zu seinem Austritt. So schaffe er sich und seinem Hause und der Gesamtgemeinde Israels Sühne!',
        18: 'Dann gehe er hinaus zum Altar, der vor dem Herrn ist, und entsündige ihn! Er nehme vom Farrenblut und vom Bocksblut und bringe dieses an die Altarhörner ringsum!',
        19: 'Er sprenge auf ihn vom Blute mit seinem Finger siebenmal! So reinige und heilige er ihn von den Unreinheiten der Söhne Israels.',
        20: 'Und hat er die Entsündigung des Heiligtums, des Festgezeltes und des Altares vollendet, dann bringe er den lebenden Bock herbei!',
        21: 'Und Aaron lege seine beiden Hände auf den Kopf des lebenden Bockes und bekenne über ihm die Schuld all der Söhne Israels und alle ihre Frevel bei all ihren Sünden und lege sie auf den Kopf des Bockes und lasse ihn durch einen blöden Menschen in die Wüste führen!',
        22: 'So trage der Bock auf sich all ihre Schuld in eine abgelegene Gegend fort! In die Wüste treibe er den Bock hinaus!',
        23: 'Aaron aber komme wieder zum Festgezelt! Hernach ziehe er die Linnenkleider aus, die er sich angelegt, als er das Heiligtum betreten, und lege sie dort nieder!',
        24: 'Dann wasche er an heiligem Ort sein Fleisch mit Wasser, ziehe seine Kleider an, gehe hinaus und richte sein und des Volkes Brandopfer her! So schaffe er sich und dem Volke Sühne!',
        25: 'Des Sündopfers Fett soll er auf dem Altar aufdampfen lassen!',
        26: 'Wer aber den Bock zu Azazel hinausschafft, soll seine Kleider waschen; dann bade er sein Fleisch in Wasser! Dann darf er ins Lager kommen.',
        27: 'Den Sündopferfarren und den Sündopferbock, deren Blut man hineinbrachte, um im Heiligtum die Sühnebräuche zu tun, soll man vor das Lager bringen, und hier verbrenne man ihre Haut, ihr Fleisch und ihren Mist!',
        28: 'Wer sie verbrennt, soll seine Kleider waschen; dann bade er sein Fleisch in Wasser! Alsdann darf er ins Lager kommen.',
        29: 'So sei es euch zu ewiger Satzung: Am zehnten Tag des siebten Monats sollt ihr euch kasteien und keine Arbeit tun, weder der Eingeborene noch der Fremdling, der bei euch weilt!',
        30: 'Denn an diesem Tage schafft man euch zu eurer Reinigung Sühne. Von all euren Sünden sollt ihr euch vor dem Herrn reinigen!',
        31: 'Ein Tag völliger Ruhe sei es für euch, und kasteit euch kraft ewiger Satzung!',
        32: 'Und die Entsündigung vollziehe der Priester, der gesalbt und eingekleidet ward, um Priesterdienst an seines Vaters Statt zu tun! Er lege die linnenen Gewänder an, die Kleider für das Allerheiligste!',
        33: 'Und er entsündige das Allerheiligste, das Festgezelt und den Altar! So soll er den Priestern und der ganzen Volksgemeinde Sühne schaffen!',
        34: 'Dies sei euch ewige Satzung, daß man den Söhnen Israels von allen ihren Sünden einmal im Jahre Sühne schaffe!" Und er tat, wie der Herr dem Moses befohlen hatte.',
    },
    17: {
        1: 'Und der Herr sprach zu Moses also:',
        2: '"Rede mit Aaron, seinen Söhnen und mit allen Söhnen Israels und sprich zu ihnen: \'Dies ist es, was der Herr gebietet:',
        3: 'Jeder vom Hause Israel, der ein Rind, ein Lamm oder eine Ziege im Lager schlachtet oder außerhalb des Lagers schlachtet',
        4: 'und sie nicht an des Festgezeltes Pforte bringt, um vor des Herrn Wohnung sie dem Herrn als Opfergabe darzubringen, dem werde es als Blutschuld angerechnet, hat er doch Blut vergossen! Dieser Mann werde aus seinem Volke gestrichen,',
        5: 'auf daß die Israeliten ihre Schlachtopfer, die sie auf freiem Feld schlachteten, zum Priester an des Festgezeltes Pforte dem Herrn bringen und sie als Dankopfer dem Herrn schlachten!',
        6: 'Der Priester besprenge mit dem Blut den Altar an des Festgezeltes Pforte und lasse das Fett aufdampfen zu süßem Duft für den Herrn!',
        7: "Sie sollen aber ihre Schlachtopfer nicht mehr den Bocksgestalten opfern, denen sie nachhuren! Dies sei ihnen ewige Satzung in ihren Geschlechtern.'",
        8: "Und du sollst ihnen sagen: 'Wer vom Hause Israel und von den Fremden, die in seiner Mitte weilen, Brand- oder Schlachtopfer darbringt",
        9: 'und es nicht vor des Festgezeltes Pforte bringt, es für den Herrn zu bereiten, ein solcher werde aus seinem Volke gestrichen!',
        10: 'Und gegen jeden vom Hause Israel und von den Fremdlingen bei ihnen, der irgend Blut genießt, will ich mein Antlitz richten und ihn aus seinem Volke streichen!',
        11: 'Des Fleisches Leben ist im Blute. Für den Altar habe ich es euch gegeben, um euch selbst Sühne zu schaffen. Denn Blut schafft Sühne durch das Leben.',
        12: 'Darum sage ich zu den Söhnen Israels: Von euch darf niemand Blut genießen, auch nicht der Fremde unter euch.',
        13: 'Und jeder Israelit und jeder ihrer Fremdlinge, der sich ein Wild erlegt oder eßbares Geflügel, lasse sein Blut auslaufen und bedecke es mit Erde!',
        14: 'Denn jedes Fleisches Leben ist sein Blut kraft seines Lebensodems. Darum sage ich zu den Söhnen Israels: Von keinem Fleische dürft ihr das Blut genießen. Denn jedes Fleisches Leben ist sein Blut. Jeder werde ausgestrichen, der es genießt!',
        15: 'Und jegliche Person, die Gefallenes oder Zerrissenes ißt, Eingeborener oder Fremdling, wasche ihre Kleider und bade sich in Wasser! Er bleibt bis zum Abend unrein.',
        16: 'Wäscht er nicht und badet er nicht seinen Leib, dann zieht er sich Schuld zu.\'"',
    },
    18: {
        1: 'Und der Herr sprach zu Moses also:',
        2: '"Rede mit den Söhnen Israels und sprich zu ihnen: \'Ich, der Herr, bin euer Gott!',
        3: 'Ihr sollt nicht nach dem Treiben des Ägypterlandes tun, in dem ihr gesessen, und nicht nach dem Treiben des Landes Kanaan, in das ich euch bringe! Ihr sollt nicht nach ihren Satzungen wandeln.',
        4: 'Meine Satzungen sollt ihr befolgen und meine Vorschriften halten, danach zu wandeln! Ich, der Herr, bin euer Gott.',
        5: 'Wahret meine Vorschriften und Satzungen! Wer sie tut, wird durch sie leben. Ich bin der Herr.',
        6: 'Niemand soll sich seinen nächsten Blutsverwandten nahen, die Blöße zu enthüllen!',
        7: 'Die Blöße deines Vaters und deiner Mutter darfst du nicht enthüllen. Deine Mutter ist es. Du darfst nicht ihre Blöße enthüllen.',
        8: 'Die Blöße deines Vaterweibes darfst du nicht enthüllen. Deines Vaters Blöße ist es.',
        9: 'Die Blöße deiner Schwester, deines Vaters Tochter oder deiner Mutter Tochter, daheim geboren oder auswärts, darfst du nicht enthüllen.',
        10: 'Die Blöße deiner Sohnestochter oder deiner Tochtertochter darfst du nicht enthüllen. Sie sind deine Blöße.',
        11: 'Die Blöße der Tochter eines Weibes deines Vaters, als deinem Vater geboren, darfst du nicht enthüllen. Sie ist deine Schwester.',
        12: 'Die Blöße der Schwester deines Vaters darfst du nicht enthüllen. Sie ist deines Vaters Leib.',
        13: 'Die Blöße der Schwester deiner Mutter darfst du nicht enthüllen. Sie ist deiner Mutter Leib.',
        14: 'Die Blöße deines Vaterbruders darfst du nicht enthüllen, noch nahe dich seinem Weib! Sie ist deine Tante.',
        15: 'Die Blöße deiner Schwiegertochter darfst du nicht enthüllen. Sie ist deines Sohnes Weib.',
        16: 'Die Blöße deines Brudersweibes darfst du nicht enthüllen. Sie ist deines Bruders Blöße.',
        17: 'Die Blöße eines Weibes und seiner Tochter darfst du nicht enthüllen. Die Tochter ihres Sohnes und die Tochter ihrer Tochter darfst du nicht nehmen, ihre Blöße zu enthüllen. Sie sind nächste Blutsverwandte. Unzucht ist es.',
        18: 'Du darfst nicht ein Weib zu seiner Schwester hinzunehmen als Nebenweib, um neben ihm zu seinen Lebzeiten ihre Blöße zu enthüllen.',
        19: 'Du darfst dich nicht einem Weib zur Zeit der Unreinheit nahen, ihre Scham zu enthüllen.',
        20: 'Mit dem Weibe eines anderen aus deinem Volke darfst du keinen Beischlaf haben, auf daß du dich dadurch nicht unrein machst.',
        21: 'Von deinen Nachkommen darfst du keinen hergeben zur Weihe an den Moloch. Du darfst nicht Gottes Namen entweihen. Ich bin der Herr.',
        22: 'Einem Manne darfst du nicht beiliegen wie einem Weibe. Ein Greuel ist es.',
        23: 'Du darfst dich nicht fleischlich mit einem Tiere vermischen, dich dadurch unrein zu machen. Nicht darf sich ein Weib vor ein Tier hinstellen, sich zu paaren. Schwere Schandtat ist es.',
        24: 'Versündigt euch nicht durch derartiges! Denn durch all das haben sich die Heiden versündigt, die ich vor euch vertreibe.',
        25: 'Das Land ward unrein, und ich suchte seine Missetaten an ihm heim. Und das Land spie seine Einwohner darum aus.',
        26: 'So haltet meine Vorschriften und Satzungen! Ihr dürft nichts von all diesen Greueln tun, weder Eingeborene noch Fremde, die bei euch weilen.',
        27: 'Denn alle diese Greuel haben im Lande die Leute getan, die vor euch waren, und das Land ward dadurch unrein.',
        28: 'Daß nicht das Land euch ausspeie, wenn ihr es verunreinigt, wie es das Volk ausgespieen hat, das vor euch war!',
        29: 'Wer einen dieser Greuel tut, ausgestrichen müssen aus dem Volke Leute werden, die solches tun.',
        30: 'So folgt meiner Anordnung, daß ihr keine dieser Greuelsitten, die vor euch getan worden sind, übet und euch dadurch unrein machet! Ich, der Herr, bin ja euer Gott.\'"',
    },
    19: {
        1: 'Und der Herr redete mit Moses also:',
        2: '"Rede mit der ganzen Gemeinschaft der Söhne Israels und sprich zu ihr: \'Seid heilig! Denn heilig bin ich, der Herr, euer Gott.',
        3: 'Ihr sollt jeder seine Mutter und seinen Vater fürchten und meine Ruhetage beobachten. Ich, der Herr, bin euer Gott!',
        4: 'Wendet euch nicht den Götzen zu! Ihr sollt euch keine gegossenen Götter machen! Ich, der Herr, bin euer Gott.',
        5: 'Und schlachtet ihr dem Herrn ein Dankopfer, so sollt ihr es zu eurer Begnadigung opfern!',
        6: 'Am Tage, da ihr es darbringt, und am Tage darauf muß es gegessen werden. Was bis zum dritten Tage übrigbleibt, soll verbrannt werden!',
        7: 'Würde es am dritten Tage gegessen, so wäre es Verdorbenes, das nicht zu Gnaden geachtet wird.',
        8: 'Wer es genießt, lädt Schuld auf sich. Denn er entheiligt das dem Herrn Geweihte. Aus seinem Volke werde diese Seele gestrichen!',
        9: 'Wenn ihr euer Land aberntet, dann darfst du dein Feld nicht bis zum letzten Rande abernten. Du sollst nicht nach deiner Ernte Nachlese halten!',
        10: 'Auch deinen Weinberg sollst du nicht nachlesen! Du sollst in deinem Weinberge nicht die zerstreuten Beeren auflesen! Du sollst sie dem Armen und dem Fremdling überlassen! Ich, der Herr, bin euer Gott.',
        11: 'Ihr sollt nicht stehlen! Ihr sollt nicht hehlen! Ihr sollt einander nicht betrügen.',
        12: 'Ihr sollt nicht bei meinem Namen falsch schwören, daß du den Namen deines Gottes entweihest! Ich bin der Herr.',
        13: 'Du sollst nicht deinen Nächsten drücken! Du sollst nicht rauben! Nicht soll bei dir des Lohnarbeiters Lohn bis zum Morgen nächtigen!',
        14: 'Du sollst nicht einem Tauben fluchen! Du sollst nicht vor den Blinden einen Anstoß legen! Fürchte dich vor deinem Gott! Ich bin der Herr.',
        15: 'Ihr sollt keine Verdrehung beim Rechtsprechen machen! Du sollst nicht den Niederen abweisen! Du sollst nicht auf einen Großen Rücksicht nehmen! Du sollst deinen Nächsten recht richten!',
        16: 'Du sollst nicht als Ohrenbläser beim Volk umhergehen! Du sollst nicht dem Blute deines Nächsten nachstellen! Ich bin der Herr.',
        17: 'Du sollst nicht deinen Bruder in deinem Herzen hassen! Mit Freimut sollst du den Angehörigen deines Volkes zurechtweisen und nicht seinetwegen Schuld auf dich laden!',
        18: 'Du sollst nicht rachgierig sein und nicht deines Volkes Söhnen grollen! Liebe deinen Nächsten wie einen deinesgleichen! Ich bin der Herr.',
        19: 'Ihr sollt meine Satzungen beobachten! Du sollst nicht zweiartig dein Vieh paaren! Du sollst nicht zweiartig dein Feld besäen! Nicht soll an dich ein Kleid, zweiartig gewebt, kommen!',
        20: 'Wohnt ein Mann einem Weibe bei und sie ist als Sklavin mit einem anderen Manne verbunden, ist aber noch nicht losgekauft oder noch nicht freigelassen, so soll man eine Unterscheidung machen! Sie soll nicht den Tod erleiden, weil sie keine Freigelassene war.',
        21: 'Er aber bringe dem Herrn als Buße an des Festgezeltes Pforte zum Schuldopfer einen Widder!',
        22: 'Der Priester schaffe ihm vor dem Herrn durch den Schuldopferwidder Sühne wegen seiner Sünde, die er getan, und suche ihm Verzeihung zu erwirken von seiner Sünde, die er tat!',
        23: 'Kommt ihr in das Land, dann pflanzt allerlei Fruchtbäume, aber scheuet das, was daran zu scheuen ist, ihre Frucht! Drei Jahre sollt ihr sie scheuen! Sie darf nicht gegessen werden!',
        24: 'Im vierten Jahre sei all ihre Frucht heilig, dem Herrn geweiht!',
        25: 'Im fünften Jahr dürft ihr ihre Früchte genießen, daß ihre Ernte euer Gut mehre. Ich, der Herr, bin euer Gott.',
        26: 'Ihr sollt nichts mit Blut essen! Ihr sollt nicht wahrsagen! Ihr sollt nicht zaubern!',
        27: 'Ihr sollt nicht eures Haupthaares Ecken runden! Du sollst nicht deines Bartes Ecken verderben!',
        28: 'Ihr sollt euch nicht wegen einer Leiche an eurem Leibe ritzen. Ihr sollt keine Schriftzeichen euch einätzen! Ich bin der Herr.',
        29: 'Entweihe deine Tochter nicht, daß du sie zur Unzucht führst, auf daß nicht das Land unzüchtig werde und sich das Land mit grober Unzucht fülle!',
        30: 'Ihr sollt meine Ruhetage halten! Ihr sollt vor meinem Heiligtum Ehrfurcht haben! Ich bin der Herr.',
        31: 'Wendet euch nicht an die Totengeister! Befragt nicht die Wahrsagegeister, daß ihr dadurch unrein würdet! Ich, der Herr, bin euer Gott.',
        32: 'Vor einem grauen Haupte sollst du aufstehen! Ehre die Person des Greises! Fürchte dich vor deinem Gott! Ich bin der Herr.',
        33: 'Weilt in eurem Lande bei euch ein Fremder, dann dürft ihr ihn nicht drücken.',
        34: 'Der Fremdling soll euch sein wie ein Eingeborener aus euch! Liebe ihn wie deinesgleichen! Ihr seid Fremdlinge im Lande Ägypten gewesen. Ich, der Herr, bin euer Gott.',
        35: 'Ihr sollt keine Verdrehung beim Rechtsprechen, beim Längenmaß, Gewicht und Gefäß machen!',
        36: 'Richtige Waage, richtige Gewichtsteine, richtiger Scheffel und richtige Kanne sollen bei euch sein! Ich, der Herr, bin euer Gott, der euch aus Ägypterland geführt hat.',
        37: 'So beachtet alle Vorschriften und Satzungen und erfüllet sie, bin ich doch der Herr!\'"',
    },
    20: {
        1: 'Und der Herr sprach zu Moses also:',
        2: '"Sprich zu den Söhnen Israels: Wer aus den Söhnen Israels und aus den Fremdlingen in Israel von seinen Kindern eines dem Moloch gibt, soll den Tod erleiden! Das Volk des Landes soll ihn steinigen!',
        3: 'Ich selber richte mein Antlitz wider diesen Mann und streiche ihn aus seinem Volke, weil er von seinen Kindern eines dem Moloch gibt und so mein Heiligtum unrein macht und meinen heiligen Namen entweiht.',
        4: 'Und wollte vor einem solchen Manne das Volk des Landes seine Augen schließen, wenn er von seinen Kindern eines dem Moloch gibt, und wollten sie ihn nicht töten,',
        5: 'dann richte ich mein Antlitz gegen einen solchen Mann und seine Sippe. Ich streiche ihn aus seinem Volke, ihn samt allen, die ihm in Unzucht mit dem Moloch nachfolgen.',
        6: 'Und gegen die Person, die sich an Toten- und an Wahrsagegeister wendet, ihnen nachzuhuren, richte ich mein Angesicht und streiche sie aus ihrem Volke.',
        7: 'Zeigt euch als heilig, daß ihr heilig werdet! Ich bin der Herr, euer Gott.',
        8: 'Beachtet und befolget meine Satzungen! Ich bin der, der euch heiligt, ich, der Herr.',
        9: 'Wer Vater und Mutter grob beleidigt, soll den Tod erleiden! Weil er Vater und Mutter grob beleidigt, bleibt seine Blutschuld auf ihm.',
        10: 'Buhlt ein Mann mit eines anderen Mannes Weib, buhlt ein Mann mit seines Nächsten Weib, so leide der Ehebrecher und die Ehebrecherin den Tod!',
        11: 'Liegt jemand bei dem Weibe seines Vaters, hat er des Vaters Blöße enthüllt, so sollen beide den Tod leiden, und ihre Blutschuld bleibt bei ihnen.',
        12: 'Liegt jemand bei der eigenen Schwiegertochter, so sollen beide den Tod leiden. Sie haben eine schwere Schandtat ausgeübt, und ihre Blutschuld bleibt bei ihnen.',
        13: 'Liegt jemand bei einem Manne, wie man bei einem Weibe liegt, so haben beide eine Greueltat getan. Den Tod sollen sie leiden, und ihre Blutschuld bleibt bei ihnen!',
        14: 'Nimmt jemand ein Weib und ihre Mutter dazu, so ist dies grobe Unzucht. Man soll ihn und sie verbrennen, auf daß nicht Unzucht unter euch im Schwange seil',
        15: 'Wer sich mit einem Tiere vermischt, soll den Tod leiden! Auch das Tier sollt ihr umbringen!',
        16: 'Naht sich ein Weib einem Tiere, sich mit ihm zu paaren, so töte Weib und Tier! Den Tod sollen sie leiden, und ihre Blutschuld bleibt bei ihnen!',
        17: 'Nimmt jemand seines Vaters Tochter oder seiner Mutter Tochter, seine Schwester, und schaut er ihre Blöße und sie schaut seine Blöße, so ist dies Verruchtheit. Sie sollen angesichts ihres Volkes ausgestrichen werden, hat er doch die Blöße seiner Schwester enthüllt; er lädt Schuld auf sich.',
        18: 'Liegt jemand bei einem Weibe in ihrem Unwohlsein und enthüllt er ihre Blöße und deckt er ihren Quell auf und enthüllt sie den Quell ihrer Blutungen, so sollen beide aus ihrem Volke gestrichen werden!',
        19: 'Enthülle nicht die Blöße deiner Mutterschwester noch der Vaterschwester! Wer seine eigenen Verwandten entblößt, ihre Schuld sollen sie büßen.',
        20: 'Liegt jemand bei der Tante, so hat er seines Oheims Blöße enthüllt. Sie laden ihre Schuld auf sich. Kinderlos werden sie sterben.',
        21: 'Nimmt jemand seines Bruders Weib, so ist es Blutschande. Er hat seines Bruders Blöße enthüllt. Kinderlos werden sie bleiben.',
        22: 'Haltet alle meine Vorschriften und Satzungen! Tut sie, daß euch das Land nicht ausspeie, in das ich euch bringe, darin zu siedeln!',
        23: 'Ihr sollt nicht nach den Satzungen der Heiden wandeln, die ich vor euch vertreibe! Denn all das haben sie getan, daß es mich vor ihnen ekelte.',
        24: 'Ich sprach zu euch: Ihr sollt ihr Land zu eigen haben. Ich gebe es euch zum Besitz, ein Land, von Milch und Honig fließend. Ich, der Herr, bin euer Gott, der euch von den anderen Völkern gesondert hat.',
        25: 'So scheidet zwischen reinem und unreinem Vieh, reinem und unreinem Geflügel! Ihr sollt euch selbst nicht abscheulich machen durch das Vieh, das Geflügel oder durch das, was auf dem Boden kriecht und was ich für euch als unrein ausgesondert habe!',
        26: 'Seid mir heilig! Denn ich, der Herr, bin heilig. Ich sondere euch von den Völkern, daß ihr mein seiet.',
        27: 'Ist in einem Mann oder Weib ein Toten- oder Wahrsagegeist, so sollen sie den Tod leiden! Man soll sie steinigen! Ihre Blutschuld bleibt bei ihnen.\'"',
    },
    21: {
        1: 'Und der Herr sprach zu Moses: "Sprich zu den Priestern, zu den Söhnen Aarons, sage ihnen: \'An keiner Leiche aus seiner Verwandtschaft darf er sich unrein machen.',
        2: 'Nur an den nächsten Blutsverwandten, an seiner Mutter, seinem Vater, seinem Sohn, seiner Tochter, seinem Bruder',
        3: 'und an seiner jungfräulichen Schwester, die ihm nahesteht und die noch keines Mannes ist, darf er sich unrein machen.',
        4: 'Er darf sich nicht als Gatte an seinen anderen Verwandten unrein machen.',
        5: 'Sie sollen auf ihrem Kopf keine Glatze machen, nicht ihres Bartes Rand scheren und in ihr Fleisch keine Einschnitte machen.',
        6: 'Heilig seien sie ihrem Gott und sie sollen ihres Gottes Namen nicht entweihen! Sie bringen ja die Mähler für den Herrn, die Speise ihres Gottes, dar. Deswegen seien sie heilig!',
        7: 'Sie dürfen keine Dirne noch eine Vergewaltigte heiraten, noch ein von seinem Manne verstoßenes Weib. Denn heilig ist er seinem Gott.',
        8: 'Heilig halte ihn! Er bringt deines Gottes Speise dar. Heilig sei er dir! Denn heilig bin ich, der Herr, der euch heiligt.',
        9: 'Entweiht sich eine Priestertochter durch Hurerei, so entweiht sie ihren Vater. Im Feuer werde sie verbrannt!',
        10: 'Der Hohepriester unter seinen Brüdern, auf dessen Haupt das Salböl ausgegossen und der eingekleidet ward durch Anlegen der Gewänder, lasse nie sein Haupthaar offen fliegen! Nicht soll er seine Kleider zerreißen!',
        11: 'Er soll zu keiner Leiche gehen! Selbst nicht des Vaters oder der Mutter wegen darf er sich unrein machen.',
        12: 'Er soll nicht aus dem Heiligtum gehen und nicht seines Gottes Heiligtum entweihen! Die Weihe durch seines Gottes Ölsalbung ruht auf ihm. Ich bin der Herr.',
        13: 'Er soll eine Jungfrau heiraten!',
        14: 'Er soll keine Witwe nehmen, noch Verstoßene, noch Vergewaltigte, noch Dirne, sondern eine Jungfrau aus der Verwandtschaft,',
        15: 'daß er nicht durch seine Verwandten seinen Stamm entweihe! Denn ich, der Herr, bin es, der ihn heiligt.\'"',
        16: 'Und der Herr sprach zu Moses also:',
        17: '"Sprich so zu Aaron: \'Hat einer aus deinem Stamme ein Gebrest, dann darf er nicht herantreten, Speise seinem Gott darzubringen.',
        18: 'Denn niemand darf herantreten, der ein Gebrest hat, kein Blinder oder Lahmer oder Entstellter oder Überlanger,',
        19: 'oder wer einen Beinbruch hat oder einen Armbruch,',
        20: 'oder ein Buckliger oder ein Zwerg oder ein Fleckäugiger oder ein Krätziger oder ein Grindiger oder einer mit zerriebenen Hoden.',
        21: 'Kein Mann, der ein Gebrest hat, vom Stamm des Priesters Aaron darf herantreten, die Mähler für den Herrn darzubringen. Hat er ein Gebrest, dann darf er nicht herantreten, die Speise seines Gottes darzubringen.',
        22: 'Die Speise seines Gottes, von den hochheiligen und selbstverständlich von den heiligen Gaben, darf er essen.',
        23: 'Nur soll er nicht zum Vorhang kommen und sich nicht dem Altare nähern, weil er ein Gebrest hat! Sonst entweiht er meine Heiligtümer. Denn ich, der Herr, bin es, der sie heiligt.\'"',
        24: 'Und Moses redete so zu Aaron und seinen Söhnen und zu allen Söhnen Israels.',
    },
    22: {
        1: 'Und der Herr redete zu Moses also.-',
        2: '"Sag dem Aaron und seinen Söhnen, sie sollen wegen der heiligen Gaben der Israeliten enthaltsam sein, auf daß sie meinen heiligen Namen nicht entweihen, wenn sie mir, dem Herrn, Gaben weihen!',
        3: "Sprich zu ihnen: 'Für eure Geschlechter! Wer von all euren Nachkommen je den heiligen Gaben naht, die dem Herrn die Israeliten weihen, solange an ihm Unreinheit ist, diese Person werde vor meinem Angesichte weggestrichen! Ich bin der Herr.",
        4: 'Wer von dem Aaronsstamm aussätzig oder flüssig ist, soll nichts von den heiligen Gaben essen, bis er wieder rein ist! Wer einen, der durch eine Leiche unrein ward, berührt, oder wem der Same entgeht,',
        5: 'wer ein Gewürm berührt, wodurch man unrein wird, oder einen Menschen, an dem man unrein wird durch irgendeine Unreinheit an ihm,',
        6: 'diese Person, die das berührt, sei bis zum Abend unrein! Sie soll nichts von heiligen Gaben essen, bevor sie ihren Leib gebadet hat!',
        7: 'Sobald die Sonne untergeht, ist er rein. Hernach mag er von heiligen Gaben essen. Denn das ist sein Brot.',
        8: 'Gefallenes und Zerrissenes darf er nicht essen, daß er nicht dadurch unrein werde. Ich bin der Herr.',
        9: 'Sie sollen meine Vorschrift befolgen, daß sie nicht deswegen Sünde auf sich laden; sie würden sterben, wenn sie es entweihen. Ich bin es, der Herr, der sie heiligt.',
        10: 'Kein Unbefugter darf Heiliges genießen. Der Beisaß des Priesters und der Lohndiener dürfen nichts Heiliges essen.',
        11: 'Erwirbt ein Priester für Geld einen Sklaven, so darf er mitessen, ebenso ein Hausgeborener. Sie dürfen von seiner Speise essen.',
        12: 'Aber eine Priestertochter, die einen Nichtpriester geheiratet hat, darf von der Weihegabe der heiligen Gaben nichts genießen.',
        13: 'Dagegen eine Priestertochter, die Witwe ist oder verstoßen und kinderlos und wieder in ihr Vaterhaus zurückkehrt, wie in der ledigen Zeit, darf von der Speise ihres Vaters essen. Ein Unzugehöriger darf aber nicht davon essen.',
        14: 'Wenn jemand aus Versehen Geheiligtes ißt, so lege er ein Fünftel des Betrages darauf und gebe es dem Priester samt der heiligen Gabe!',
        15: 'Sie sollen nicht entweihen der Israeliten heilige Gaben, die sie dem Herrn als Weihegabe darbringen!',
        16: 'Sonst würden sie ihnen Schuldverfehlungen aufladen, wenn sie ihre heiligen Gaben essen. Denn ich, der Herr, bin es, der sie heiligt.\'"',
        17: 'Und der Herr sprach zu Moses:',
        18: '"Sprich zu Aaron, seinen Söhnen und zu allen Israeliten und sage zu ihnen: \'Bringt vom Hause Israels oder von den Fremdlingen in Israel jemand sein Opfer dar, sei es versprochen oder freiwillig, das er dem Herrn als Brandopfer darbringen will,',
        19: 'so sei es zu eurer Begnadigung ein fehlerloses männliches Tier von Rindern, Lämmern oder Ziegen!',
        20: 'Was einen Makel an sich hat, dürft ihr nicht darbringen. Es würde euch nicht zur Begnadigung sein.',
        21: 'Will jemand dem Herrn ein Dankopfer darbringen, als besonderes Opfer für Gelobtes oder als freiwillige Gabe von Rindern oder Schafen, so sei es für die Begnadigung fehlerlos! Keinen Makel darf es an sich haben.',
        22: 'Was blind ist oder gebrochen oder verstümmelt oder geschwürig oder krätzig oder grindig, das dürft ihr dem Herrn nicht darbringen und nicht als Mahl für den Herrn auf den Altar legen.',
        23: 'Ein Rind oder ein Schaf, überdeckt oder verkrüppelt, darfst du als freie Gabe herrichten. Aber als Gelübdeopfer wird es nicht angerechnet.',
        24: 'Zerquetschtes oder Zerstoßenes oder Abgerissenes oder Verschnittenes dürft ihr dem Herrn nicht darbringen. Ihr dürft in eurem Lande solches nicht machen.',
        25: 'Auch von Ausländern dürft ihr nichts von alledem als Speise eures Gottes darbringen. Ihr Verderb ist an ihnen. Gebrest ist daran. Solches wird euch nicht angerechnet.\'"',
        26: 'Und der Herr redete zu Moses also:',
        27: '"Wenn ein Rind, ein Lamm oder ein Zicklein geworfen wird, soll es sieben Tage unter seiner Mutter sein! Vom achten Tage ab und weiterhin kann es als Opfer, als Mahl für den Herrn, angesehen werden.',
        28: 'Ihr dürft weder Rind noch Schaf an einem Tag mit seinem Jungen schlachten.',
        29: 'Wollt ihr dem Herrn ein Lobesopfer opfern, so sollt ihr es zu eurer Begnadigung opfern!',
        30: 'Am selben Tage noch werde es gegessen! Ihr dürft davon nichts bis zum Morgen übriglassen! Ich bin der Herr.',
        31: 'Beachtet meine Vorschriften! Tut sie! Ich bin der Herr.',
        32: 'Ihr sollt nicht meinen heiligen Namen entweihen! Ich will geheiligt sein bei den Söhnen Israels. Ich, der Herr, bin es, der euch heiligt,',
        33: 'der euch aus dem Ägypterland geführt, um euch Gott zu sein. Ich bin der Herr."',
    },
    23: {
        1: 'Und der Herr sprach zu Moses also:',
        2: '"Rede mit den Söhnen Israels und sprich zu ihnen: \'Des Herrn Feste, die ihr als heilige Vorlesungstage feiern sollt, dies sind meine Feste:',
        3: 'Sechs Tage soll Arbeit getan werden. Der siebte aber ist ein Tag unbedingter Ruhe, ein heiliger Vorlesungstag. Da dürft ihr keine Arbeit tun. Ein Ruhetag des Herrn ist er in allen euren Siedlungen.',
        4: 'Dies sind des Herrn Feste, die heiligen Vorlesungstage, die ihr zu ihrer Zeit begehen sollt.',
        5: 'Am vierzehnten des ersten Monats gegen Abend ist Passah für den Herrn.',
        6: 'Am fünfzehnten desselben Monats ist das Fest der ungesäuerten Brote für den Herrn. Ihr sollt sieben Tage ungesäuertes Brot genießen.',
        7: 'Am ersten Tage habt ihr heilige Vorlesung abzuhalten. Ihr dürft keinerlei Dienstarbeit tun.',
        8: 'Sieben Tage bringet dem Herrn ein Mahl dar! Am siebten Tage ist heilige Vorlesung. Ihr dürft keinerlei Dienstarbeit tun.\'"',
        9: 'Und der Herr redete zu Moses:',
        10: '"Rede mit den Söhnen Israels und sprich zu ihnen: \'Kommt ihr in das Land, das ich euch gebe, und haltet ihr darin die Ernte, so bringt eurer Ernte erste Abhubsgarbe dem Priester!',
        11: 'Er bringe die Garbe vor den Herrn, euch zur Begnadigung! Am Morgen nach dem Sabbat soll sie der Priester darbringen!',
        12: 'Bereitet an dem Tage, da ihr die Garbe bringt, für den Herrn ein fehlerloses, noch nicht einjähriges Lamm zum Brandopfer!',
        13: 'Dazu als Speiseopfer zwei Zehntel feines Mehl, mit Öl bereitet, als ein Mahl süßen Duftes für den Herrn, dazu einen vierter Krug Wein als Trankopfer!',
        14: 'Brot, geröstete, zerstoßene Körner, dürft ihr bis zu eben dem Tage nicht essen, bis ihr für euren Gott die Opfergabe dargebracht. Dies ist ewige Satzung für eure Geschlechter in all euren Siedlungen.',
        15: 'Dann zählt für euch von dem Tage nach dem Sabbat, vom Tage, wo ihr die Garbe dargebracht, sieben volle Wochen ab!',
        16: 'Bis zum Tage nach dem siebten Sabbat sollt ihr fünfzig Tage abzählen! Dann bringt dem Herrn ein neues Speiseopfer dar!',
        17: 'Aus euren Siedlungen sollt ihr zwei Weihebrote aus zwei Zehntel feinem Mehl bringen, mit Sauerteig gebacken, als Erstlingsopfer für den Herrn!',
        18: 'Und zu dem Brote bringt noch sieben fehlerlose Lämmer, noch nicht ein Jahr alt, einen jungen Stier und zwei Widder! Sie sollen ein Brandopfer dem Herrn sein, nebst ihren Speis- und Trankopfern, als ein Mahl süßen Duftes für den Herrn!',
        19: 'Dann bereitet einen Ziegenbock zum Sündopfer sowie zwei Lämmer, nicht ein Jahr alt, zum Dankopfer!',
        20: 'Der Priester bringe sie mit den Erstlingsbroten vor dem Herrn samt den beiden Lämmern dar! Zu des Priesters Nutzen seien sie dem Herrn geweiht!',
        21: 'An eben diesem Tage haltet eine Vorlesung ab! Heilige Vorlesung sei es euch! Ihr dürft keinerlei Dienstarbeit verrichten. Dies ist ewige Satzung in allen euren Siedlungen für eure Geschlechter.',
        22: 'Und wenn ihr euer Land aberntet, so sollst du dein Feld nicht bis zum Rande abernten und nach deiner Ernte keine Nachlese halten! Dem Armen und dem Fremdling sollst du es lassen! Ich, der Herr, bin euer Gott.\'"',
        23: 'Der Herr redete mit Moses:',
        24: '"Sprich also zu den Söhnen Israels: \'Der erste im siebten Monate soll euch ein Ruhetag sein, ein freudiges Gedächtnis, eine heilige Vorlesung!',
        25: 'Ihr dürft keinerlei Dienstarbeit tun. Dagegen bringt dem Herrn ein Mahl dar!\'"',
        26: 'Und der Herr redete mit Moses:',
        27: '"Genau der zehnte Tag desselben siebten Monats ist der Sühnetag. Da sollt ihr eine heilige Vorlesung abhalten und euch kasteien und dem Herrn ein Mahl darbringen!',
        28: 'Aber keinerlei Arbeit dürft ihr an eben diesem Tage tun. Ein Sühnetag ist es, um euch Sühne zu schaffen vor dem Herrn, eurem Gott.',
        29: 'Denn alle die Personen, die sich nicht an eben diesem Tage kasteien, sind aus den Reihen ihres Volkes zu streichen.',
        30: 'Und alle die Personen, die an eben diesem Tag irgendeine Arbeit tun, raffe ich aus ihrem Volke weg.',
        31: 'Ihr dürft keinerlei Arbeit tun. Dies ist ewige Satzung in allen euren Siedlungen für eure Geschlechter.',
        32: 'Er sei für euch ein strenger Ruhetag! Kasteiet euch! Am neunten Tage des Monats abends, vom Abend bis zum Abend, sollt ihr Sabbatruhe halten!"',
        33: 'Und der Herr redete mit Moses:',
        34: '"Sprich also zu den Söhnen Israels: Am fünfzehnten desselben siebten Monats feiere man dem Herrn sieben Tage lang das Laubhüttenfest!',
        35: 'Am ersten Tage ist heilige Vorlesung. Ihr dürft keinerlei Dienstarbeit tun.',
        36: 'Ihr sollt sieben Tage dem Herrn ein Mahl bringen! Am achten Tage haltet heilige Vorlesung ab und bringt dann dem Herrn ein Mahl! Tag der Festversammlung ist es. Ihr dürft keinerlei Dienstarbeit tun.',
        37: 'Dies sind des Herrn Feste, an denen ihr heiligen Vorlesungen obliegen sollt, dabei dem Herrn ein Mahl darbringend, Brand-, Speise-, Schlacht- und Trankopfer je nach Erfordernis des Tages,',
        38: 'abgesehen von den Sabbaten des Herrn und euren Gaben, allen euren gelobten Opfern und euren freien Spenden, die ihr dem Herrn geben werdet.',
        39: 'Genau am fünfzehnten des siebten Monats, wenn ihr des Landes Ernte einheimset, sollt ihr das Fest des Herrn sieben Tage feiern! Ein Ruhetag ist der erste Tag, ebenso der achte.',
        40: 'Am ersten Tage holt euch Zweige vom Myrtenbaum, Palmfächer und Zweige von Laubbäumen und Bachweiden! Und freut euch vor dem Herrn, eurem Gotte, sieben Tage!',
        41: 'So feiert es im Jahre sieben Tage als Fest des Herrn, ewiges Gesetz für eure Geschlechter! Im siebten Monat sollt ihr es feiern.',
        42: 'Sieben Tage sollt ihr in den Lauben wohnen! Jeder Eingeborene in Israel soll in den Lauben wohnen,',
        43: 'damit eure Geschlechter wissen, daß ich die Söhne Israels in Lauben habe siedeln lassen, als ich sie aus Ägypterland geführt! Ich, der Herr, bin euer Gott."',
        44: 'Und Moses verkündete die Feste den Söhnen Israels.',
    },
    24: {
        1: 'Und der Herr redete mit Moses also:',
        2: '"Befiehl den Söhnen Israels, sie sollen dir lauteres Öl aus zerstoßenen Oliven für den Leuchter liefern, um ein stetes Licht zu haben!',
        3: 'Draußen vor des Zeugnisses Vorhang im Festgezelt mache es Aaron zurecht für die Zeit vom Abend bis zum Morgen vor dem Herrn! Eine ewige Satzung für eure Geschlechter!',
        4: 'Auf dem reingoldenen Leuchter soll er die Lichter zurechtmachen, ständig vor dem Herrn!',
        5: 'Nimm feines Mehl und backe daraus zwölf Kuchen! Zwei Zehntel soll auf einen Kuchen kommen!',
        6: 'Lege sie in zwei Reihen, je sechs für einen Teil, vor dem Herrn auf einen Tisch von reinem Gold!',
        7: 'Und jedem Teile gib reinen Weihrauch bei, damit er dem Brot als Brandteile diene, ein Mahl für den Herrn!',
        8: 'Er soll es jedesmal am Sabbat stets vor dem Herrn aufschichten, von den Söhnen Israels aus eine ewige Verpflichtung!',
        9: 'Es gehöre Aaron und seinen Söhnen! Sie sollen es an heiliger Stätte verzehren! Denn ihm gehört es als Hochheiliges von des Herrn Mählern, ein ewiges Anrecht."',
        10: 'Da war eines israelitischen Weibes Sohn mit ausgezogen, dessen Vater ein Ägypter war, unter den Israeliten. Nun rauften im Lager der Sohn der Israelitin und ein israelitischer Mann.',
        11: 'Da schmähte des israelitischen Weibes Sohn den Namen und lästerte. Da brachten sie ihn zu Moses. Seine Mutter aber vom Stamme Dan hieß Selomit, Dibris Tochter.',
        12: 'Sie führten ihn in den Gewahrsam, bis aus des Herrn Mund ihnen Weisung käme.',
        13: 'Und der Herr redete mit Moses:',
        14: '"Führe den Lästerer vor das Lager! Alle, die es hörten, sollen die Hände auf sein Haupt legen! Dann soll ihn die gesamte Gemeinde steinigen!',
        15: "Und zu den Söhnen Israels sprich also: 'Wer seinen Gott lästert, lädt Schuld auf sich.",
        16: 'Wer aber des Herrn Namen schmäht, leide den Tod! Ihn soll die Gesamtgemeinde steinigen. Sei es Fremdling oder Eingeborener! Weil er den Namen geschmäht, muß er sterben.',
        17: 'Wer ein Menschenwesen erschlägt, soll den Tod erleiden!',
        18: 'Wer ein Tierwesen erschlägt, soll es ersetzen! Wesen um Wesen.',
        19: 'Wenn jemand seinem Nächsten einen Leibesschaden zufügt, dem werde getan, wie er getan!',
        20: "Bruch um Bruch! Aug' um Aug'! Zahn um Zahn! Der gleiche Leibesschaden, den er einem anderen zufügt, werde ihm zugefügt!",
        21: 'Wer ein Stück Vieh erschlägt, soll es ersetzen! Wer einen Menschen erschlägt, soll getötet werden.',
        22: 'Einerlei Recht sei euch, dem Fremdling wie dem Einheimischen! Ich, der Herr, bin euer Gott.\'"',
        23: 'Und Moses berichtete so den Israeliten. Da führten sie den Lästerer vor das Lager und steinigten ihn. Die Israeliten taten also, wie der Herr dem Moses befohlen hatte.',
    },
    25: {
        1: 'Der Herr aber hatte zu Moses auf dem Berge Sinai also gesprochen:',
        2: '"Rede mit den Söhnen Israels und sprich zu ihnen: \'Wenn ihr in das Land kommt, das ich euch gebe, so halte das Land für den Herrn eine Ruhezeit!',
        3: 'Sechs Jahre sollst du dein Feld besäen! Sechs Jahre sollst du deinen Weinberg beschneiden, dann heimse seine Ernte!',
        4: 'Im siebten Jahre aber soll das Land volle Ruhe haben, als Ruhezeit für den Herrn! Du darfst dein Feld nicht besäen, noch deine Weinberge beschneiden!',
        5: 'Den Nachwuchs deiner Ernte sollst du nicht beschneiden! Die Trauben deines unbeschnittenen Weinstocks sollst du nicht lesen. Ein Ruhejahr soll es für das Land sein.',
        6: 'Während eurer Bodenruhe diene zur Nahrung dir, deinem Knechte, deiner Magd, deinem Lohnarbeiter, deinem Beisaß unter deinem Schutze,',
        7: 'deinem Vieh und dem Wilde in deinem Lande all sein Ertrag.',
        8: 'Zähle dir sieben Jahrwochen ab, siebenmal sieben Jahre! So seien dir die Tage der sieben Jahrwochen neunundvierzig Jahre!',
        9: 'Dann laß im siebten Mond das Lärmhorn erschallen, am zehnten Tage des Monats! Am Sühnetage sollt ihr in eurem Lande das Horn ertönen lassen!',
        10: 'Heiligt das fünfzigste Jahr und ruft Freiheit im Land für alle seine Insassen aus! Jubeljahr sei es euch! Da kehrt ein jeder zu seinem Besitz und jeder zu seiner Sippe zurück!',
        11: 'Jubeljahr sei euch das fünfzigste Jahr! Nicht säen dürft ihr noch den Nachwuchs einernten und nicht von unbeschnittenen Traubenstöcken lesen!',
        12: 'Ein Jubeljahr soll euch heilig sein! Vom Felde weg sollt ihr seinen Ertrag verzehren!',
        13: 'In diesem Jubeljahr kommt ihr jeder wieder zu seinem Besitz.',
        14: 'Verkauft ihr etwas einem Angehörigen eures Volkes oder kauft ihr es von einem solchen, so plage keiner den anderen!',
        15: 'Nach der Zahl der Jahre nach dem Jubeljahr sollst du den Angehörigen deines Volkes abkaufen! Nach der Zahl der Erntejahre soll er dir verkaufen!',
        16: 'Für eine größere Zahl von Jahren sollst du einen höheren Kaufpreis zahlen und einen kleineren für eine kleinere Zahl von Jahren! Wenn er dir eine Anzahl Ernten verkauft,',
        17: 'dann sollt ihr nicht einander plagen, einer den anderen Angehörigen seines Volkes! Fürchte dich vor deinem Gott! Denn ich, der Herr, bin euer Gott.',
        18: 'Tut meine Vorschriften! Meine Satzungen sollt ihr wahren! Erfüllt sie! Dann wohnet ihr im Lande sicher.',
        19: 'Und dann gibt das Land seine Frucht. Satt könnt ihr euch essen und sicher darin siedeln.',
        20: 'Und sprächet ihr: "Was sollen wir im siebten Jahre essen? Wir dürfen ja nicht säen und keinen Vorrat sammeln",',
        21: 'so entbiete ich im sechsten Jahre meinen Segen für euch, daß es für drei Jahre Ertrag gibt.',
        22: 'Sät ihr im achten Jahr, so könnt ihr noch Altes vom Ertrag genießen. Bis zum neunten Jahre, bis seine Ernte kommt, könnt ihr Altes essen.',
        23: 'Nicht soll das Land endgültig verkauft werden! Denn mein ist das Land. Ihr seid nur Gäste und Beisassen bei mir.',
        24: 'Ihr sollt überall in eurem eigenen Lande Wiedereinlösung für das Land gestatten',
        25: 'Verarmt dein Bruder und verkauft von seinem Besitz, so gehe sein nächster Verwandter zu ihm als Löser und löse den Verkauf seines Bruders aus!',
        26: 'Hat jemand keinen Löser, aber ist er zur Wiedereinlösung vermöglich,',
        27: 'so bringe er die Jahre seit dem Verkauf in Anrechnung! Was darüber ist, erstatte er seinem Käufer, damit er wieder zu seinem Besitz komme!',
        28: 'Ist er aber zur Rückerstattung unvermögend, dann bleibe sein Verkauf im Besitz des Käufers bis zum Jubeljahr! Im Jubeljahr aber falle es heim, daß er wieder zu seinem Besitz kommt!',
        29: 'Verkauft jemand in einer ummauerten Stadt ein Wohnhaus, so währe sein Einlösungsrecht bis zum Tage des Jahres seines Verkaufes! Sein Einlösungsrecht soll auf den Tag währen!',
        30: 'Wird es aber bis zum Ablauf eines vollen Jahres nicht eingelöst, dann verfalle das Haus in der Stadt mit Mauern endgültig seinem Käufer und seinen Nachkommen! Im Jubeljahr fällt es nicht heim.',
        31: 'Die Häuser in Dörfern ohne Ringmauern sind zum Ackerfelde zu rechnen. Für sie gibt es ein Einlösungsrecht; sie fallen im Jubeljahre heim.',
        32: 'Bei den Levitenhäusern, bei ihren eigenen Häusern in den Städten, gibt es stets ein Einlösungsrecht.',
        33: 'Wer von den Leviten nicht einlösen kann, dessen verkauftes Haus falle in der eigenen Stadt im Jubeljahr zurück. Denn der Levitenstädte Häuser sind ihr Eigentum inmitten der Söhne Israels.',
        34: 'Aber ihrer Städte Weideland darf nicht verkauft werden. Für alle Zeit gehört es ihnen.',
        35: 'Verarmt dein Bruder, zittert seine Hand neben dir, dann halte ihn fest! Als Gast und Beisasse, so lebe er bei dir!',
        36: 'Nimm keinen Wucherzins von ihm! Fürchte deinen Gott! Dein Bruder lebe neben dir!',
        37: 'Du sollst ihm dein Geld nicht gegen Zins geben und nicht um Zinsen deine Speise.',
        38: 'Ich, der Herr, bin euer Gott, der aus Ägypterland euch geführt, euch das Land von Kanaan zu geben und euch Gott zu sein.',
        39: 'Verarmt dein Bruder neben dir und verkauft er sich dir, so sollst du ihn keine Sklavendienste tun lassen!',
        40: 'Er soll bei dir wie ein Lohnarbeiter sein, ein Beisasse! Er soll bei dir bis zum Jubeljahr dienen!',
        41: 'Dann verlasse er samt seinen Söhnen dich und kehre zu seiner Sippe! Zum Besitz seiner Väter kehre er wieder!',
        42: 'Sie sind ja meine Knechte, die ich aus Ägypterland geführt. Sie dürfen nicht wie Sklaven verkauft werden.',
        43: 'Du sollst nicht mit Härte über ihn herrschen! Fürchte dich vor deinem Gott!',
        44: 'Dein Sklave und deine Sklavin, die dein sind: von den Heidenvölkern rings um euch rnöget ihr Sklaven und Sklavinnen erwerben.',
        45: 'Auch von den Kindern der Beisassen neben euch möget ihr kaufen sowie aus ihrer Sippe bei euch. Die sie in eurem Land gezeugt, sie mögen euer Besitz werden.',
        46: 'Vererbet sie nach euch auf eure Söhne als ihren Besitz! Ihr möget sie dauernd zu Sklaven haben. Aber über eure israelitischen Brüder dürft ihr gegenseitig nicht mit Härte walten.',
        47: 'Kommt bei dir ein Fremder oder Beisaß zu Besitz, dein Bruder aber wird neben ihm arm und verkauft sich einem Beisassen bei dir oder einem Abkömmling aus des Fremdlings Sippe,',
        48: 'so gibt es nach seinem Verkauf für ihn Auslösung. Einer seiner Brüder soll ihn lösen,',
        49: 'oder sein Oheim oder seines Oheims Sohn, oder einer seiner nächsten Blutsverwandten seiner Sippe, oder reicht sein Vermögen zu, so löse er sich aus!',
        50: 'Er rechne mit seinem Käufer die Zeit vom Jahre seines Verkaufs bis zum Jubeljahr! Der Preis seines Verkaufs sei nach der Jahre Zahl! Wie ein Lohnarbeiter soll er eine bestimmte Zeit bei ihm sein!',
        51: 'Sind es noch viele der Jahre, dann soll er dementsprechend seine Lösungssumme von seinem Kaufgeld erstatten!',
        52: 'Fehlen aber nur wenige Jahre bis zum Jubeljahr, so berechne er sie ihm! Nach seinen Jahren soll er seine Lösungssumme erstatten!',
        53: 'Gleich dem, der Jahr für Jahr um Lohn arbeitet, soll er neben ihm sein! Er soll aber nicht mit Härte über ihn walten vor deinen Augen!',
        54: 'Wird er nicht auf diese Weise ausgelöst, dann gehe er im Jubeljahr samt seinen Söhnen frei aus!',
        55: 'Denn die Söhne Israels sind mir Knechte. Meine Knechte sind sie, die ich aus dem Ägypterland herausgeführt. Ich, der Herr, bin euer Gott.\'"',
    },
    26: {
        1: '"Ihr sollt keine Götzen machen! Ihr sollt euch kein Schnitzbild errichte und kein Steinmal! Ihr sollt keinen Klagestein in eurem Lande setzen, um euch darauf hinzuwerfen! Denn ich, der Herr, bin euer Gott.',
        2: 'Meine Ruhetage sollt ihr beobachten! Vor meinem Heiligtume sollt ihr Ehrfurcht haben! Ich bin der Herr.',
        3: 'Wandelt ihr nach meinen Satzungen und haltet ihr meine Vorschriften und tut ihr nach ihnen,',
        4: 'alsdann gebe ich eure Regen zu ihrer Zeit. Das Land gibt seine Ernte und des Feldes Baum seine Frucht.',
        5: 'Dann reicht euch die Dreschzeit bis zur Weinlese und die Weinlese bis zur Saatzeit. Ihr eßt bis zum Sattsein euer Brot und sitzt in Sicherheit in eurem Lande.',
        6: 'Dem Land gebe ich Frieden. Ihr legt euch nieder, und niemand schreckt euch. Böses Getier schaffe ich aus dem Lande. Kein Schwert zieht mehr durch euer Land.',
        7: 'Verfolgt ihr eure Feinde, dann verfallen sie vor euch dem Schwerte!',
        8: 'Eurer fünf verfolgen hundert und eurer hundert zehntausend. So verfallen eure Feinde vor euch dem Schwert.',
        9: 'Ich wende mich euch zu und mehre euch und mache euch zahlreich. Meinen Bund errichte ich mit euch.',
        10: 'Essen könnt ihr Altes, Gelagertes. Das Alte aber müßt ihr erst hinausschaffen vor dem Neuen.',
        11: 'Ich nehme meinen Wohnsitz bei euch, und meine Seele wird euch nicht verabscheuen.',
        12: 'Ich wandle unter euch und bin euch Gott. Ihr aber sollt mir zum Volke sein!',
        13: 'Ich, der Herr, bin euer Gott, der aus Ägypterland euch geführt, damit ihr nicht länger ihnen Sklaven wäret. Ich zerbrach die Stangen eures Joches und ließ euch aufrecht gehen.',
        14: 'Hört ihr aber nicht auf mich und tut ihr nicht nach allen den Geboten,',
        15: 'verwerft ihr meine Vorschriften und verabscheut eure Seele meine Satzungen, daß alle meine Gebote ungetan bleiben, daß ihr meinen Bund brechet,',
        16: 'dann tu ich Ähnliches an euch. Ich verhänge über euch plötzlich Schwindsucht und Brand, die die Augen vernichten und die Seele verkümmern. Umsonst sät ihr euren Samen. Eure Feinde verzehren ihn.',
        17: 'Ich kehre mein Antlitz wider euch. Von euren Feinden werdet ihr geschlagen, und eure Hasser unterjochen euch. Ihr flieht, wo keiner euch verfolgt.',
        18: 'Gehorcht ihr mir auf dies hin nicht, dann züchtige ich euch noch siebenmal härter für eure Sünden.',
        19: 'Ich breche euren frechen Übermut und lasse euren Himmel wie Eisen werden, euer Ackerfeld wie Erz.',
        20: 'Umsonst verzehrt sich eure Kraft. Ertraglos bleibt euer Ackerfeld. Des Feldes Bäume geben keine Frucht.',
        21: 'Und geht ihr dann mit mir noch unschicklich um, und wollt ihr mir nicht gehorchen, dann schlage ich euch nach euren Sünden siebenfach.',
        22: 'Ich sende gegen euch des Feldes Wild, damit es euch entvölkere und euer Vieh würge und euch mindere, damit eure Straßen veröden.',
        23: 'Und nehmt ihr dann noch keine Zucht von mir an,',
        24: 'dann gehe auch ich mit euch unschicklich um und schlage euch siebenfach um eurer Sünde willen.',
        25: 'Ich bringe über euch ein Schwert, das den Bundesbruch rächt. Bergt ihr euch in euren Städten, dann sende ich unter euch die Pest. In Feindeshände werdet ihr gegeben.',
        26: 'Zerbreche ich euch des Brotes Stütze, dann können euer Brot zehn Weiber in einem einzigen Ofen backen. Sie werden euch das Brot zuwägen. Dann esset ihr und werdet nicht satt.',
        27: 'Und hört ihr trotzdem nicht auf mich, und geht ihr mit mir unschicklich um,',
        28: 'dann gehe auch ich in meinem Grimm mit euch unschicklich um und züchtige euch meinerseits um eurer Sünden willen siebenfach.',
        29: 'Dann eßt ihr eurer Söhne Fleisch, und eurer Töchter Fleisch werdet ihr essen.',
        30: 'Und ich verwüste eure Höhen, zerstöre eure Rauchaltäre und werfe auf eure Götzen eure Leichen. So ekelt sich meine Seele vor euch.',
        31: 'Ich mache zu Trümmern eure Städte und lasse eure Heiligtümer unbewohnt und nicht mehr rieche ich euren süßen Duft.',
        32: 'Ich verwüste das Land, und eure Feinde entsetzen sich darob, wenn sie in ihm siedeln.',
        33: 'Euch aber zerstreue ich unter die Heiden und ich zücke hinter euch ein Schwert. Zur Wüste soll euer Land werden, zu Trümmern eure Städte!',
        34: 'Dann zahlt das Land seine Sabbate mit all der Zeit der Verödung, indessen ihr im Lande eurer Feinde seid. Dann feiert das Land und zahlt so seine Sabbate.',
        35: 'Ruhe hat es die ganze Zeit der Verödung, die Ruhe, die es nicht gehabt, als ihr bei euren Ruhezeiten darin noch wohntet.',
        36: 'Die von euch übrigbleiben, mache ich verzagt in ihrer Feinde Länder. Verwehten Blattes Rauschen schlägt sie in die Flucht. Sie fliehen wie auf Schwertes Flucht und stürzen, obwohl sie niemand verfolgt.',
        37: 'Sie fallen wie vor einem Schwerte, der eine über den anderen, obschon von niemandem verfolgt. Ihr haltet vor euren Feinden nicht stand.',
        38: 'Und bei den Heiden schwindet ihr, und eurer Feinde Land frißt euch.',
        39: 'Die von euch übrigbleiben, siechen ob ihrer Sündenschuld in eurer Feinde Ländern hin. Sie siechen obendrein ob ihrer Väter Sünden hin.',
        40: 'Bekennen sie dann ihre Schuld und die der Väter, in ihrem Trug, mit dem sie mich betrogen, auch daß sie mit mir unschicklich umgegangen',
        41: 'und daß auch ich mit ihnen unschicklich gehandelt und sie in ihrer Feinde Land verbracht, wenn sich dann ihr unbeschnitten Herze beugt und wenn sie dann ihre Sündenschuld aufzählen,',
        42: 'dann gedenke ich meines Jakobbundes und meines Isaakbundes und meines Abrahambundes und des Landes gedenke ich.',
        43: 'Das Land muß aber von ihnen verlassen werden und seine Sabbate abzahlen, indes es wüste liegt und jene fort sind. Sie selber müssen ihre Sündenschuld aufzählen, weil sie meine Satzungen verworfen und meine Vorschriften mißachtet haben.',
        44: 'Trotzdem verwerfe ich sie nicht, wenn sie im Lande ihrer Feinde sind, und ich verabscheue sie nicht, so daß ich sie ganz vertilgt und meinen Bund mit ihnen aufgelöst hätte. Ich, der Herr, bin ihr Gott.',
        45: 'Ich gedenke zu ihrem Besten des Bundes mit den Ahnen, die ich aus Ägypterland vor der Heiden Augen weggeführt, um ihnen Gott zu sein, ich, der Herr."',
        46: 'Dies sind die Gebote, Satzungen und Lehren, die der Herr zwischen sich und den Söhnen Israels auf dem Berge Sinai durch Moses aufgestellt hat.',
    },
    27: {
        1: 'Und der Herr sprach zu Moses:',
        2: '"Sprich zu den Söhnen Israels und sage ihnen: \'Wenn jemand Personen nach dem Schätzungswert dem Herrn gelobt,',
        3: 'dann sei Schätzungswert des Männlichen von zwanzig bis zu sechzig Jahren nach heiligem Gewicht fünfzig Silberringe!',
        4: 'Ist es ein Weibliches, sei der Wert dreißig Ringe!',
        5: 'Ist es von fünf bis zu zwanzig Jahren, so sei der Wert des Männlichen zwanzig Ringe, der des Weiblichen zehn!',
        6: 'Ist es von einem Monat bis zu fünf Jahren, so sei der Wert des Männlichen fünf Silberringe, der des Weiblichen drei Silberringe!',
        7: 'Ist es von sechzig Jahren und darüber, so sei der Wert des Männlichen fünfzehn Ringe und der des Weibes zehn!',
        8: 'Ist es aber zu arm für den Schätzungswert, dann bringe man es vor den Priester, und der Priester werte es! Nach dem, was der Gelobende zahlen kann, soll ihn der Priester werten!',
        9: 'Und ist es Vieh, von dem man dem Herrn ein Opfer bringen will, dann soll alles, was einer davon gibt, dem Herrn geheiligt sein!',
        10: 'Er soll es nicht auswechseln und nicht Gutes für Schlechtes vertauschen oder Schlechtes für Gutes, und tauscht er doch das eine Vieh mit dem anderen, so sei das eine geheiligt; aber auch das andere soll es sein!',
        11: 'Ist es aber irgendein unreines Tier, das man dem Herrn nicht als Opfer darbringen darf, so stelle er das Vieh dem Priester vor!',
        12: 'Der Priester werte es zwischen gut und schlecht! Wie es der Priester wertet, so soll es bleiben!',
        13: 'Löst er es aber ein, so lege er ein Fünftel auf den Schätzungswert!',
        14: 'Weiht jemand dem Herrn sein Haus als heilige Gabe, so werte es der Priester zwischen gut und schlecht! Wie es der Priester schätzt, dabei soll es bleiben!',
        15: 'Will jemand, der sein Haus geweiht hat, es einlösen, so lege er ein Fünftel des Wertes darauf, und es sei wieder sein!',
        16: 'Weiht jemand etwas von seinem Besitz dem Herrn, so sei der Wert nach seiner Aussaat! Ein Malter Gerstenaussaat zu fünfzig Silberringen.',
        17: 'Weiht er vom Jubeljahre ab sein Feld, so soll es nach dem Richtwerte zu stehen kommen!',
        18: 'Weiht er aber nach dem Jubeljahr sein Feld, so berechne der Priester den Silberpreis mit Rücksicht nach den Jahren, die bis zum Jubeljahre fehlen! Dies werde vom Richtwert abgezogen!',
        19: 'Will aber der, der das Feld geweiht, es einlösen, dann lege er ein Fünftel des Wertes darauf, und es sei wieder sein!',
        20: 'Löst er aber das Feld nicht ein und hat man das Feld an einen anderen verkauft, so kann es nicht mehr eingelöst werden.',
        21: 'Vielmehr ist dies Feld, wird es im Jubeljahre frei, etwas, was dem Herrn geweiht ist, wie ein dem Bann verfallenes Feld. Dem Priester soll sein Besitz zufallen.',
        22: 'Weiht er jedoch dem Herrn ein Feld, das er sich selbst gekauft und das nicht zu seinem Erbbesitz gehört,',
        23: 'so berechne ihm der Priester den Betrag des Richtwertes bis zum Jubeljahr! Er gebe den Wert an demselben Tag als heilige Gabe für den Herrn!',
        24: 'Im Jubeljahre kommt das Feld an den zurück, von dem er es gekauft und dem es als Erbbesitz gehört hat.',
        25: 'Nach heiligem Gewicht geschehe jede Schätzung! Zwanzig Korn seien ein Ring!',
        26: 'Erstgeburten aber, die beim Vieh als erstgeworfen des Herrn sind, darf niemand opfern, weder Rind noch Schaf. Dem Herrn gehören sie ohnehin.',
        27: 'Bei unreinem Vieh löse man es nach dem Schätzungswert und lege ein Fünftel des Betrags darauf! Wird es nicht eingelöst, so werde es nach dem Wert verkauft!',
        28: 'Keinerlei Banngut, das ein Mann dem Herrn bannt, nichts, was ihm gehört, Mensch oder Vieh oder Erbgrundstück, darf verkauft oder eingelöst werden. Alles Banngut ist dem Herrn hochheilig.',
        29: 'Was von Menschen gebannt wird, darf nicht losgekauft werden. Es soll getötet werden!',
        30: 'Aller Zehnte vom Boden, der Saatfrucht und der Baumfrüchte sind des Herrn. Sie sind dem Herrn geheiligt.',
        31: 'Löst aber jemand einen Teil von seinem Zehnten ein, so soll er ein Fünftel des Betrages darauflegen!',
        32: 'Bei allem Zehnten von Rind und Schaf, von allem, was unterm Hirtenstabe durchgeht, soll das zehnte Stück dem Herrn geheiligt werden.',
        33: 'Man soll nicht zwischen gut und schlecht untersuchen! Man soll es nicht vertauschen! Tauschte man es doch, dann sei das eine dem Heiligtum verfallen, ebenso soll es mit dem anderen sein! Es darf nicht eingelöst werden.\'"',
        34: 'Dies sind die Gebote, die der Herr dem Moses für die Israeliten auf dem Berge Sinai gegeben hat.',
    },
}
